-- rowstile 0.1.0-beta.4: rowstile_0_1_0_beta_4. Generated by rowstile migrate from the policy; don't edit it,
-- change the policy and write the next migration.
-- rowstile 0.1.0-beta.3 -> 0.1.0-beta.4: what the new version makes differently

-- a migration is one transaction: outside one, nothing below changes anything
SELECT pg_catalog.set_config('authz_ctx.migration', '854fc775273a02f0', true);
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM '854fc775273a02f0' THEN
    PERFORM pg_catalog.set_config('authz_migration.read_only', pg_catalog.current_setting('default_transaction_read_only'), false);
    PERFORM pg_catalog.set_config('default_transaction_read_only', 'on', false);
  END IF;
END $authz_tx$;
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM '854fc775273a02f0' THEN
    RAISE EXCEPTION 'rowstile: this migration must run in one transaction, and its statements are being committed one by one [AZ615]'
      USING HINT = 'nothing was changed, and this session is read-only until the migration''s last statement; run the file with your migration tool, or with psql -1 -f';
  END IF;
END $authz_tx$;

SELECT pg_catalog.set_config('lock_timeout', '10s', true) WHERE pg_catalog.current_setting('lock_timeout') IN ('0', '0ms');
SELECT pg_catalog.set_config('check_function_bodies', 'off', true);

-- this migration starts from the policy the previous one left
DO $authz_guard$
DECLARE v_lock text;
BEGIN
  IF to_regclass('authz.policy_versions') IS NOT NULL THEN
    EXECUTE 'SELECT lock FROM authz.policy_versions ORDER BY id DESC LIMIT 1' INTO v_lock;
  END IF;
  IF v_lock = '854fc775273a02f0' THEN
    RAISE EXCEPTION 'rowstile: this database already holds what this migration brings (it ran here before, or rowstile dev or push took the database there): don''t run it, tell your migration tool it is applied [AZ607]'
      USING HINT = 'Prisma: prisma migrate resolve --applied <the migration''s folder>. Alembic: alembic stamp head. '
                   'Others, and why: rowstile help AZ607';
  ELSIF v_lock IS DISTINCT FROM '97264d75d32c98be' THEN
    RAISE EXCEPTION 'rowstile: this migration changes the policy the migration before it left (%), but the database has % [AZ607]',
      '97264d75d32c98be', coalesce(v_lock, 'none')
      USING HINT = 'apply the migrations in order; a database changed with rowstile push or apply since needs the '
                   'migrations from the start (or rowstile apply of the policy the previous migration left) '
                   '(rowstile help AZ607)';
  END IF;
END $authz_guard$;

-- the triggers given to the tables under others: made again below, on what this migration makes
-- @locks ACCESS EXCLUSIVE: the partitions and child tables of the tables rowstile watches
DO $authz_ch$
DECLARE r record;
BEGIN
  FOR r IN SELECT g.tgname, g.tgrelid::regclass AS tbl FROM pg_catalog.pg_trigger g
           JOIN pg_catalog.pg_description d ON d.objoid = g.oid AND d.classoid = 'pg_catalog.pg_trigger'::regclass
           WHERE d.description = 'rowstile: the trigger of the table above, for the rows stored here' LOOP
    EXECUTE pg_catalog.format('DROP TRIGGER %I ON %s', r.tgname, r.tbl);
  END LOOP;
END $authz_ch$;

-- what goes, or is made again
DROP TRIGGER IF EXISTS "authz_document_col_audit_trunc" ON "app"."documents";
DROP TRIGGER IF EXISTS "authz_document_forget_trunc" ON "app"."documents";
DROP TRIGGER IF EXISTS "authz_document_forget_trunc_first" ON "app"."documents";
DROP TRIGGER IF EXISTS "authz_rel_audit_1_trunc" ON "app"."team_members";
DROP TRIGGER IF EXISTS "authz_team_col_audit_trunc" ON "app"."teams";
DROP TRIGGER IF EXISTS "authz_team_forget_trunc" ON "app"."teams";
DROP TRIGGER IF EXISTS "authz_team_forget_trunc_first" ON "app"."teams";
DROP TRIGGER IF EXISTS "authz_user_col_audit_trunc" ON "app"."users";
DROP TRIGGER IF EXISTS "authz_user_forget_trunc" ON "app"."users";
DROP TRIGGER IF EXISTS "authz_user_forget_trunc_first" ON "app"."users";
DROP TRIGGER IF EXISTS "authz_user_keys_gone_trunc" ON "app"."users";
DROP TRIGGER IF EXISTS "authz_user_keys_gone_trunc_first" ON "app"."users";
DROP TRIGGER IF EXISTS authz_shares_canon ON authz.shares;
DROP FUNCTION IF EXISTS
  authz_int."document__edit__why"(p_id bigint, p_depth int, p_seen text[]),
  authz_int."document__editor__why"(p_id bigint, p_depth int, p_seen text[]),
  authz_int."document__owner__why"(p_id bigint, p_depth int, p_seen text[]),
  authz_int."document__share__why"(p_id bigint, p_depth int, p_seen text[]),
  authz_int."document__view__why"(p_id bigint, p_depth int, p_seen text[]),
  authz_int."document__viewer__why"(p_id bigint, p_depth int, p_seen text[]),
  authz_int."team__member__why"(p_id bigint, p_depth int, p_seen text[]);

-- The app role must not be the policy's owner, nor a member of it: the rules would not hold for it
DO $ar$
DECLARE v_app name;
BEGIN
  SELECT a.rolname INTO v_app FROM pg_catalog.pg_roles a
  WHERE a.rolname = 'starter_app' AND NOT a.rolsuper AND pg_catalog.pg_has_role(a.oid, CURRENT_USER, 'MEMBER');
  IF v_app IS NOT NULL THEN
    RAISE EXCEPTION 'the app role % is the role that applies the policy (%), or a member of it: the rules would not hold for it [AZ624]', v_app, CURRENT_USER
      USING HINT = 'the policy''s owner skips row-level security, may turn it off, and is believed without a signature: the app connects as a role of its own, which owns nothing of the database';
  END IF;
END $ar$;

-- Functions below resolve names with the search_path in effect now: the schemas that exist, temporary schema last
DO $sp$
DECLARE v_path text; v_bad text; f record;
BEGIN
  SELECT pg_catalog.string_agg(pg_catalog.format('%I (%s)', pw.schema, pw.who), ', ') INTO v_bad FROM (SELECT n.nspname::text AS schema, w.who
FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) s(name) JOIN pg_catalog.pg_namespace n ON n.nspname = s.name,
LATERAL (SELECT CASE WHEN EXISTS (SELECT 1 FROM pg_catalog.aclexplode(n.nspacl) a
                                  WHERE a.grantee = 0 AND a.privilege_type = 'CREATE') THEN 'PUBLIC'
                ELSE (SELECT pg_catalog.string_agg(ro.rolname::text, ', ' ORDER BY ro.rolname) FROM pg_catalog.pg_roles ro
                      WHERE pg_catalog.has_schema_privilege(ro.oid, n.oid, 'CREATE') AND NOT ro.rolsuper
                        AND ro.rolname <> 'pg_database_owner' AND NOT pg_catalog.pg_has_role(ro.oid, CURRENT_USER, 'MEMBER')
                        AND NOT pg_catalog.pg_has_role(ro.oid, (SELECT d.datdba FROM pg_catalog.pg_database d
                                                               WHERE d.datname = pg_catalog.current_database()), 'MEMBER'))
                END AS who) w
-- a temporary schema is the session's own, and never searched for functions or operators
WHERE w.who IS NOT NULL AND n.nspname !~ '^pg_(toast_)?temp_') pw;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'the search path has schemas that roles other than the owner may create objects in: % [AZ612]', v_bad
      USING HINT = 'rowstile''s functions that run as the owner resolve names on this path, so a function made there could run as the owner: revoke CREATE on those schemas, or apply with a search path without them';
  END IF;
  SELECT pg_catalog.string_agg(pg_catalog.quote_ident(s.name), ', ' ORDER BY s.i) INTO v_path
  FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) WITH ORDINALITY s(name, i)
  WHERE s.name::text !~ '^pg_temp_';
  PERFORM pg_catalog.set_config('search_path', pg_catalog.concat_ws(', ', v_path, 'pg_temp'), true);
  -- functions made before (a migration keeps those it doesn't change) take the same path
  FOR f IN SELECT p.oid::regprocedure AS fn FROM pg_catalog.pg_proc p
           WHERE p.pronamespace IN (SELECT n.oid FROM pg_catalog.pg_namespace n WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int'))
             AND EXISTS (SELECT 1 FROM pg_catalog.unnest(p.proconfig) c
                         WHERE c ^@ 'search_path=' AND c <> 'search_path=pg_catalog, pg_temp'
                           AND c <> 'search_path=' || pg_catalog.current_setting('search_path')) LOOP
    EXECUTE pg_catalog.format('ALTER FUNCTION %s SET search_path FROM CURRENT', f.fn);
  END LOOP;
END $sp$;

-- Base objects (kept across re-applies)
CREATE SCHEMA IF NOT EXISTS authz;
REVOKE ALL ON SCHEMA authz FROM PUBLIC;

-- Shares people create in the app, for relations marked 'shared' (and custom role assignments)
CREATE TABLE IF NOT EXISTS authz.shares (
  object_type      text        NOT NULL,
  object_id        text        NOT NULL,
  relation         text        NOT NULL,
  subject_type     text        NOT NULL,
  subject_id       text        NOT NULL,
  subject_relation text        NOT NULL DEFAULT '',
  expires_at       timestamptz,
  created_by       text,
  starts_at        timestamptz,
  caveat           text,
  caveat_args      jsonb,
  created_at       timestamptz DEFAULT now(),
  PRIMARY KEY (object_type, object_id, relation, subject_type, subject_id, subject_relation));
CREATE INDEX IF NOT EXISTS shares_by_subject
  ON authz.shares (subject_type, subject_id, subject_relation, object_type, relation);
REVOKE ALL ON authz.shares FROM PUBLIC;
-- A share with anyone names no one: its id is '*' and its relation '', whatever it was made with (authz_int.canon,
-- authz.share). One stored with others takes them; of two that are then one share, the one stored so stays, else
-- the first made
DELETE FROM authz.shares g USING (
  SELECT s.ctid AS row, row_number() OVER (PARTITION BY s.object_type, s.object_id, s.relation
                                           ORDER BY (s.subject_id, s.subject_relation) <> ('*', ''), s.created_at, s.ctid) AS n
  FROM authz.shares s WHERE s.subject_type = 'anyone') d
WHERE g.ctid = d.row AND d.n > 1;
UPDATE authz.shares SET subject_id = '*', subject_relation = ''
WHERE subject_type = 'anyone' AND (subject_id, subject_relation) <> ('*', '');

-- Custom roles: sets of permissions defined as data, assigned like shares ('role:<id>')
CREATE TABLE IF NOT EXISTS authz.roles (
  id          bigserial PRIMARY KEY,
  owner_type  text NOT NULL,
  owner_id    text NOT NULL,
  object_type text NOT NULL,
  name        text NOT NULL,
  created_by  text,
  created_at  timestamptz DEFAULT now(),
  UNIQUE (owner_type, owner_id, object_type, name));
CREATE TABLE IF NOT EXISTS authz.role_permissions (
  role_id    bigint NOT NULL REFERENCES authz.roles ON DELETE CASCADE,
  permission text   NOT NULL,
  PRIMARY KEY (role_id, permission));
REVOKE ALL ON authz.roles, authz.role_permissions FROM PUBLIC;

-- API keys (only a hash of each is kept)
CREATE TABLE IF NOT EXISTS authz.api_keys (
  id           bigserial PRIMARY KEY,
  user_id      text NOT NULL,
  name         text NOT NULL,
  prefix       text NOT NULL,
  hash         text NOT NULL UNIQUE,
  scopes       text NOT NULL DEFAULT '',
  created_at   timestamptz NOT NULL DEFAULT now(),
  expires_at   timestamptz,
  last_used_at timestamptz,
  revoked_at   timestamptz,
  -- whose key: user_id is the principal's id, of this type
  principal_type text NOT NULL DEFAULT 'user');
-- a principal's keys: listed, and deleted with its row
CREATE INDEX IF NOT EXISTS api_keys_by_principal ON authz.api_keys (principal_type, user_id);
-- Settings for the functions (jwt_secret, jwt_issuer, jwt_audience, jwt_user_claim, jwt_type_claim, ...)
CREATE TABLE IF NOT EXISTS authz.settings (key text PRIMARY KEY, value text NOT NULL);
-- The audit trail: every share, role, key, request and impersonation, and relationship changes
CREATE TABLE IF NOT EXISTS authz.audit (
  id               bigserial PRIMARY KEY,
  at               timestamptz NOT NULL DEFAULT clock_timestamp(),
  txid             bigint NOT NULL DEFAULT txid_current(),
  db_role          text,
  user_id          text,
  acting_user      text,
  action           text NOT NULL,
  object_type      text,
  object_id        text,
  relation         text,
  subject_type     text,
  subject_id       text,
  subject_relation text,
  detail           jsonb,
  reason           text);
CREATE INDEX IF NOT EXISTS audit_by_object ON authz.audit (object_type, object_id, at);
REVOKE ALL ON authz.api_keys, authz.settings, authz.audit FROM PUBLIC;

-- For each object with a share that starts or ends later: the next such time, when authz.announce_timed_shares()
-- announces the object (each share's write puts its times in, a run works out the next). A database made before
-- it: the times its shares have after the last run, as that run (timed_shares_to) left them
-- @object table authz.shares_due
DO $due$ BEGIN
  IF to_regclass('authz.shares_due') IS NULL THEN
    CREATE TABLE authz.shares_due (
      object_type text        NOT NULL,
      object_id   text        NOT NULL,
      at          timestamptz NOT NULL,
      PRIMARY KEY (object_type, object_id));
    INSERT INTO authz.shares_due
    SELECT g.object_type, g.object_id, min(v.at) FROM authz.shares g CROSS JOIN LATERAL (VALUES (g.starts_at), (g.expires_at)) v(at)
    WHERE v.at > coalesce((SELECT s.value::timestamptz FROM authz.settings s WHERE s.key = 'timed_shares_to'), '-infinity')
    GROUP BY g.object_type, g.object_id;
  END IF;
END $due$;
CREATE INDEX IF NOT EXISTS shares_due_by_at ON authz.shares_due (at);
REVOKE ALL ON authz.shares_due FROM PUBLIC;
-- (what an earlier authz.announce_timed_shares() kept, the end of its last run, and the indexes it read: no more)
DELETE FROM authz.settings WHERE key = 'timed_shares_to';
DROP INDEX IF EXISTS authz.shares_by_end, authz.shares_by_start;

-- Change feed: objects whose access may have changed, for caches, search indexes, file stores
CREATE TABLE IF NOT EXISTS authz.changes (
  pos         bigserial PRIMARY KEY,
  at          timestamptz NOT NULL DEFAULT clock_timestamp(),
  txid        bigint NOT NULL DEFAULT txid_current(),
  object_type text NOT NULL,
  object_ids  text[] NOT NULL,
  cause       text NOT NULL);
-- the feed's order: by transaction, then position (authz.changes_since)
CREATE INDEX IF NOT EXISTS changes_in_order ON authz.changes (txid, pos);
-- Access requests, approvals, and emergency access
CREATE TABLE IF NOT EXISTS authz.requests (
  id          bigserial PRIMARY KEY,
  object_type text NOT NULL,
  object_id   text NOT NULL,
  relation    text NOT NULL,
  requester   text NOT NULL,
  reason      text,
  duration    interval,
  status      text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'denied', 'cancelled')),
  decided_by  text,
  decided_at  timestamptz,
  note        text,
  created_at  timestamptz NOT NULL DEFAULT now());
-- the pending requests of an object, and a requester's: cancelled when their row goes (decided ones stay, history)
CREATE INDEX IF NOT EXISTS requests_by_object ON authz.requests (object_type, object_id) WHERE status = 'pending';
CREATE INDEX IF NOT EXISTS requests_by_requester ON authz.requests (requester) WHERE status = 'pending';
-- Access reviews: a snapshot of the shares on an object, each kept or revoked by a reviewer
CREATE TABLE IF NOT EXISTS authz.reviews (
  id          bigserial PRIMARY KEY,
  object_type text NOT NULL,
  object_id   text NOT NULL,
  created_by  text,
  created_at  timestamptz NOT NULL DEFAULT now(),
  closes_at   timestamptz,
  closed_at   timestamptz);
CREATE TABLE IF NOT EXISTS authz.review_items (
  review_id        bigint NOT NULL REFERENCES authz.reviews ON DELETE CASCADE,
  item             int    NOT NULL,
  relation         text   NOT NULL,
  subject_type     text   NOT NULL,
  subject_id       text   NOT NULL,
  subject_relation text   NOT NULL,
  expires_at       timestamptz,
  keep             boolean,
  decided_by       text,
  decided_at       timestamptz,
  PRIMARY KEY (review_id, item));
-- The SELECT that masks took away from a role, to give back when they go: the table-wide SELECT, replaced by
-- column privileges (whole), and the SELECT of their own that masked columns had (cols)
CREATE TABLE IF NOT EXISTS authz.masked_tables (
  tbl   text,
  role  text,
  whole boolean NOT NULL,
  cols  text[] NOT NULL,
  PRIMARY KEY (tbl, role));
REVOKE ALL ON authz.changes, authz.requests, authz.reviews, authz.review_items, authz.masked_tables FROM PUBLIC;

-- Every policy the rowstile command applied or removed, with the rowstile version that did it
CREATE TABLE IF NOT EXISTS authz.policy_versions (
  id      bigserial PRIMARY KEY,
  at      timestamptz NOT NULL DEFAULT now(),
  by_role text NOT NULL DEFAULT current_user,
  action  text NOT NULL CHECK (action IN ('apply', 'remove')),
  policy  text,
  files   jsonb NOT NULL DEFAULT '{}',
  version text NOT NULL,
  -- what the migrations' lock file said about this policy (its hash), for the next migration to check
  lock    text);
REVOKE ALL ON authz.policy_versions FROM PUBLIC;

-- Request context for conditions: SET LOCAL authz_ctx.mfa = 'yes', then {authz.ctx('mfa') = 'yes'}. A key
-- not set is NULL. Once a connection has set a key, Postgres reads it as '' in a later transaction that didn't, so
-- '' is NULL too: what an earlier request on a pooled connection set must not show
CREATE OR REPLACE FUNCTION authz.ctx(key text) RETURNS text LANGUAGE sql STABLE AS
  $$ SELECT nullif(current_setting('authz_ctx.' || key, true), '') $$;

-- Link tokens the request presents: SET LOCAL authz_ctx.links = '<token>,<token>'
CREATE OR REPLACE FUNCTION authz.link_hashes() RETURNS text[] LANGUAGE sql STABLE AS $$
  SELECT coalesce(array_agg(encode(sha256(convert_to(btrim(x), 'UTF8')), 'hex')), '{}')
  FROM unnest(string_to_array(nullif(current_setting('authz_ctx.links', true), ''), ',')) x
  WHERE btrim(x) <> '' $$;

DO $chk$
DECLARE missing text := ''; v_oid oid; v_type text; v_n int;
BEGIN
  IF to_regclass('"app"."users"') IS NULL THEN
    missing := missing || E'\n  ' || 'line 5: table app.users not found [AZ601]';
  ELSIF NOT EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = to_regclass('"app"."users"')
                    AND attname = 'id' AND attnum > 0 AND NOT attisdropped) THEN
    missing := missing || E'\n  ' || 'line 5: column id not found in app.users [AZ601]';
  END IF;
  IF to_regclass('"app"."teams"') IS NULL THEN
    missing := missing || E'\n  ' || 'line 7: table app.teams not found [AZ601]';
  ELSIF NOT EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = to_regclass('"app"."teams"')
                    AND attname = 'id' AND attnum > 0 AND NOT attisdropped) THEN
    missing := missing || E'\n  ' || 'line 7: column id not found in app.teams [AZ601]';
  END IF;
  IF to_regclass('"app"."team_members"') IS NULL THEN
    missing := missing || E'\n  ' || 'line 8: table app.team_members not found [AZ601]';
  ELSIF NOT EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = to_regclass('"app"."team_members"')
                    AND attname = 'team_id' AND attnum > 0 AND NOT attisdropped) THEN
    missing := missing || E'\n  ' || 'line 8: column team_id not found in app.team_members [AZ601]';
  END IF;
  IF to_regclass('"app"."team_members"') IS NULL THEN
    missing := missing || E'\n  ' || 'line 8: table app.team_members not found [AZ601]';
  ELSIF NOT EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = to_regclass('"app"."team_members"')
                    AND attname = 'user_id' AND attnum > 0 AND NOT attisdropped) THEN
    missing := missing || E'\n  ' || 'line 8: column user_id not found in app.team_members [AZ601]';
  END IF;
  IF to_regclass('"app"."documents"') IS NULL THEN
    missing := missing || E'\n  ' || 'line 10: table app.documents not found [AZ601]';
  ELSIF NOT EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = to_regclass('"app"."documents"')
                    AND attname = 'id' AND attnum > 0 AND NOT attisdropped) THEN
    missing := missing || E'\n  ' || 'line 10: column id not found in app.documents [AZ601]';
  END IF;
  IF to_regclass('"app"."documents"') IS NULL THEN
    missing := missing || E'\n  ' || 'line 11: table app.documents not found [AZ601]';
  ELSIF NOT EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = to_regclass('"app"."documents"')
                    AND attname = 'owner_id' AND attnum > 0 AND NOT attisdropped) THEN
    missing := missing || E'\n  ' || 'line 11: column owner_id not found in app.documents [AZ601]';
  END IF;
  IF to_regclass('"app"."documents"') IS NULL THEN
    missing := missing || E'\n  ' || 'line 23: table app.documents not found [AZ601]';
  ELSIF NOT EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = to_regclass('"app"."documents"')
                    AND attname = 'owner_id' AND attnum > 0 AND NOT attisdropped) THEN
    missing := missing || E'\n  ' || 'line 23: column owner_id not found in app.documents [AZ601]';
  END IF;
  SELECT atttypid, replace(format_type(atttypid, NULL), 'character varying', 'varchar') INTO v_oid, v_type
  FROM pg_attribute WHERE attrelid = to_regclass('"app"."users"') AND attname = 'id' AND attnum > 0 AND NOT attisdropped;
  IF FOUND AND v_oid <> to_regtype('bigint') THEN
    missing := missing || E'\n  ' || 'line 5: app.users.id is ' || v_type
      || ', not bigint: write its type after the key, (id ' || v_type || ') [AZ602]';
  END IF;
  SELECT atttypid, replace(format_type(atttypid, NULL), 'character varying', 'varchar') INTO v_oid, v_type
  FROM pg_attribute WHERE attrelid = to_regclass('"app"."teams"') AND attname = 'id' AND attnum > 0 AND NOT attisdropped;
  IF FOUND AND v_oid <> to_regtype('bigint') THEN
    missing := missing || E'\n  ' || 'line 7: app.teams.id is ' || v_type
      || ', not bigint: write its type after the key, (id ' || v_type || ') [AZ602]';
  END IF;
  SELECT atttypid, replace(format_type(atttypid, NULL), 'character varying', 'varchar') INTO v_oid, v_type
  FROM pg_attribute WHERE attrelid = to_regclass('"app"."documents"') AND attname = 'id' AND attnum > 0 AND NOT attisdropped;
  IF FOUND AND v_oid <> to_regtype('bigint') THEN
    missing := missing || E'\n  ' || 'line 10: app.documents.id is ' || v_type
      || ', not bigint: write its type after the key, (id ' || v_type || ') [AZ602]';
  END IF;
  SELECT count(*) INTO v_n FROM authz.shares g WHERE g.object_type = 'user'
    AND NOT pg_catalog.pg_input_is_valid(g.object_id, 'bigint');
  IF v_n > 0 THEN
    missing := missing || E'\n  ' || 'line 5: ' || v_n || ' shares of user name ids a bigint can''t read (their rows are gone): delete them first, as rowstile help AZ627 says [AZ627]';
  END IF;
  SELECT count(*) INTO v_n FROM authz.shares g WHERE g.object_type = 'team'
    AND NOT pg_catalog.pg_input_is_valid(g.object_id, 'bigint');
  IF v_n > 0 THEN
    missing := missing || E'\n  ' || 'line 7: ' || v_n || ' shares of team name ids a bigint can''t read (their rows are gone): delete them first, as rowstile help AZ627 says [AZ627]';
  END IF;
  SELECT count(*) INTO v_n FROM authz.shares g WHERE g.object_type = 'document'
    AND NOT pg_catalog.pg_input_is_valid(g.object_id, 'bigint');
  IF v_n > 0 THEN
    missing := missing || E'\n  ' || 'line 10: ' || v_n || ' shares of document name ids a bigint can''t read (their rows are gone): delete them first, as rowstile help AZ627 says [AZ627]';
  END IF;
  IF missing <> '' THEN RAISE EXCEPTION 'the policy does not match this database:%', missing; END IF;
END $chk$;

-- HMAC-SHA256 of who is signed in, this backend and this transaction
CREATE OR REPLACE FUNCTION authz_int.session_sig() RETURNS text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE k authz_int.session_key;
BEGIN
  SELECT * INTO k FROM authz_int.session_key;
  RETURN pg_catalog.encode(pg_catalog.sha256(k.opad || pg_catalog.sha256(k.ipad || pg_catalog.convert_to(pg_catalog.to_jsonb(ARRAY[coalesce(pg_catalog.current_setting('authz.user_id', true), ''), coalesce(pg_catalog.current_setting('authz.principal_type', true), ''), coalesce(pg_catalog.current_setting('authz.scopes', true), ''), coalesce(pg_catalog.current_setting('authz.acting_user', true), ''), pg_catalog.pg_backend_pid()::text, (EXTRACT(epoch FROM pg_catalog.transaction_timestamp()) * 1000000)::bigint::text])::text, 'UTF8'))), 'hex');
END $f$;

-- Are the settings to be believed? PL/pgSQL, so its plans are kept for the session, and not a definer: all its
-- callers run as the owner. (OR runs left to right: the refusal is asked only when the signature doesn't match.)
-- The two signatures are compared through their hashes: the time it takes says nothing of how many characters of
-- the one given are right.
CREATE OR REPLACE FUNCTION authz_int.session_ok() RETURNS boolean
LANGUAGE plpgsql STABLE SET search_path = pg_catalog, pg_temp AS $f$
DECLARE k authz_int.session_key;
BEGIN
  SELECT * INTO k FROM authz_int.session_key;
  RETURN pg_catalog.sha256(pg_catalog.convert_to(coalesce(current_setting('authz.session', true), ''), 'UTF8'))
         = pg_catalog.sha256(pg_catalog.convert_to(pg_catalog.encode(pg_catalog.sha256(k.opad || pg_catalog.sha256(k.ipad || pg_catalog.convert_to(pg_catalog.to_jsonb(ARRAY[coalesce(pg_catalog.current_setting('authz.user_id', true), ''), coalesce(pg_catalog.current_setting('authz.principal_type', true), ''), coalesce(pg_catalog.current_setting('authz.scopes', true), ''), coalesce(pg_catalog.current_setting('authz.acting_user', true), ''), pg_catalog.pg_backend_pid()::text, (EXTRACT(epoch FROM pg_catalog.transaction_timestamp()) * 1000000)::bigint::text])::text, 'UTF8'))), 'hex'), 'UTF8'))
         OR authz_int.session_refused();
END $f$;

-- A transaction is one principal's: act_as and the logins refuse to sign in someone else (nobody included) once
-- someone is signed in, and to sign in again at all once the transaction views as someone or is limited by scopes
-- (that would end what limits it). Signing in from nobody to someone, and as the same principal again, are fine.
-- Only a sign-in made in this transaction counts (its signature): the policy's owner and superusers say who is
-- signed in by hand, and aren't held to it. rowstile's own functions that ask as others and put back the caller
-- (who, explain, who_among, the invariants) switch without it.
CREATE FUNCTION authz_int.one_principal(p_type text, p_id text) RETURNS void
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE k authz_int.session_key; v_id text := coalesce(current_setting('authz.user_id', true), '');
        v_type text := coalesce(current_setting('authz.principal_type', true), '');
BEGIN
  IF pg_has_role(session_user, (SELECT nspowner FROM pg_namespace WHERE nspname = 'authz_int'), 'MEMBER') THEN
    RETURN;
  END IF;
  SELECT * INTO k FROM authz_int.session_key;
  -- (compared through their hashes, as session_ok() does)
  IF pg_catalog.sha256(pg_catalog.convert_to(coalesce(current_setting('authz.session', true), ''), 'UTF8'))
     <> pg_catalog.sha256(pg_catalog.convert_to(pg_catalog.encode(pg_catalog.sha256(k.opad || pg_catalog.sha256(k.ipad || pg_catalog.convert_to(pg_catalog.to_jsonb(ARRAY[coalesce(pg_catalog.current_setting('authz.user_id', true), ''), coalesce(pg_catalog.current_setting('authz.principal_type', true), ''), coalesce(pg_catalog.current_setting('authz.scopes', true), ''), coalesce(pg_catalog.current_setting('authz.acting_user', true), ''), pg_catalog.pg_backend_pid()::text, (EXTRACT(epoch FROM pg_catalog.transaction_timestamp()) * 1000000)::bigint::text])::text, 'UTF8'))), 'hex'), 'UTF8')) THEN
    RETURN;  -- nobody signed in in this transaction yet
  END IF;
  IF coalesce(current_setting('authz.acting_user', true), '') <> '' THEN
    RAISE EXCEPTION 'this transaction views as user %, so it can''t sign in again', v_id
      USING ERRCODE = 'invalid_authorization_specification',
      HINT = 'a transaction is one principal''s: sign in in a transaction of its own (rowstile help AZ716)';
  END IF;
  IF v_id <> '' AND (v_id, v_type) IS DISTINCT FROM (coalesce(p_id, ''), coalesce(p_type, '')) THEN
    RAISE EXCEPTION 'this transaction is signed in as % already, so it can''t sign in as %',
      CASE WHEN v_type = '' THEN 'user ' || v_id ELSE v_type || ' ' || v_id END,
      CASE WHEN coalesce(p_id, '') = '' THEN 'nobody' WHEN coalesce(p_type, '') = '' THEN 'user ' || p_id
           ELSE p_type || ' ' || p_id END
      USING ERRCODE = 'invalid_authorization_specification',
      HINT = 'a transaction is one principal''s: sign in in a transaction of its own (rowstile help AZ716)';
  END IF;
  IF coalesce(current_setting('authz.scopes', true), '') <> '' THEN
    RAISE EXCEPTION 'this transaction is limited by scopes (%), so it can''t sign in again',
      current_setting('authz.scopes', true) USING ERRCODE = 'invalid_authorization_specification',
      HINT = 'a transaction is one principal''s: sign in in a transaction of its own (rowstile help AZ716)';
  END IF;
END $f$;

-- act_as's work: with p_check, held to one principal a transaction (authz.act_as); without, for rowstile's own
-- functions that sign others in as they ask and put back the caller (who_among)
CREATE FUNCTION authz_int.act_as(p_type text, p_id text, p_check boolean) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_id text; v_type text;
BEGIN
  IF p_id IS NOT NULL AND coalesce(p_type, 'user') <> 'user'
     AND NOT EXISTS (SELECT 1 FROM authz_int.types WHERE name = p_type AND principal) THEN
    RAISE EXCEPTION '% is not a type that signs in', p_type USING
      HINT = 'principal types are marked "principal" in the policy: type service = app.services principal (rowstile help AZ707)';
  END IF;
  -- stored as every other id is ('05' is 5), so the audit and created_by name the user as shares do
  v_id := coalesce(authz_int.canon(coalesce(p_type, 'user'), p_id), '');
  v_type := CASE WHEN p_id IS NULL OR coalesce(p_type, 'user') = 'user' THEN '' ELSE p_type END;
  IF p_check THEN
    PERFORM authz_int.one_principal(v_type, v_id);
  END IF;
  PERFORM set_config('authz.user_id', v_id, true);
  PERFORM set_config('authz.principal_type', v_type, true);
  PERFORM set_config('authz.scopes', '', true);
  PERFORM set_config('authz.acting_user', '', true);
  PERFORM authz_int.sign();
  PERFORM authz_int.jit_off();
END $f$;

-- an id as it is stored and compared: '(1, 42)' -> '(1,42)', '007' -> '7', anyone's -> '*' (invalid ids
-- as they are)
CREATE OR REPLACE FUNCTION authz_int.canon(p_type text, p_id text) RETURNS text
LANGUAGE plpgsql STABLE SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  CASE p_type
    WHEN 'user' THEN
      IF pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN p_id::bigint::text; END IF;
    WHEN 'team' THEN
      IF pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN p_id::bigint::text; END IF;
    WHEN 'document' THEN
      IF pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN p_id::bigint::text; END IF;
    WHEN 'anyone' THEN RETURN '*';  -- one subject, whatever id names it
    ELSE NULL;
  END CASE;
  RETURN p_id;
END $f$;

-- shares written directly get canonical ids too
CREATE OR REPLACE FUNCTION authz_int.shares_canon() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  NEW.object_id := authz_int.canon(NEW.object_type, NEW.object_id);
  NEW.subject_id := authz_int.canon(NEW.subject_type, NEW.subject_id);
  IF NEW.subject_type = 'anyone' THEN NEW.subject_relation := ''; END IF;
  RETURN NEW;
END $f$;

CREATE TRIGGER authz_shares_canon BEFORE INSERT OR UPDATE OF object_type, object_id, subject_type, subject_id,
  subject_relation ON authz.shares FOR EACH ROW EXECUTE FUNCTION authz_int.shares_canon();

-- per-type indexes on share ids, for lookups by object
DO $gi$
DECLARE i record;
BEGIN
  FOR i IN SELECT c.relname FROM pg_index x JOIN pg_class c ON c.oid = x.indexrelid
           WHERE x.indrelid = 'authz.shares'::regclass AND c.relname LIKE 'shares\_obj\_%'
             AND c.relname <> ALL (ARRAY['shares_obj_user_bigint', 'shares_obj_team_bigint', 'shares_obj_document_bigint']::text[]) LOOP
    EXECUTE format('DROP INDEX authz.%I', i.relname);
  END LOOP;
END $gi$;
-- @object index authz."shares_obj_user_bigint"
DO $si$
BEGIN
  CREATE INDEX IF NOT EXISTS "shares_obj_user_bigint" ON authz.shares ((object_id::bigint), relation) WHERE object_type = 'user';
EXCEPTION WHEN invalid_text_representation THEN
  RAISE EXCEPTION '%: shares of user whose ids a bigint can''t read were deleted, but a transaction open since before still sees them, and so does the index applying makes of their ids: apply again once it ends, as rowstile help AZ627 says [AZ627]', 'line 5';
END $si$;
-- @object index authz."shares_obj_team_bigint"
DO $si$
BEGIN
  CREATE INDEX IF NOT EXISTS "shares_obj_team_bigint" ON authz.shares ((object_id::bigint), relation) WHERE object_type = 'team';
EXCEPTION WHEN invalid_text_representation THEN
  RAISE EXCEPTION '%: shares of team whose ids a bigint can''t read were deleted, but a transaction open since before still sees them, and so does the index applying makes of their ids: apply again once it ends, as rowstile help AZ627 says [AZ627]', 'line 7';
END $si$;
-- @object index authz."shares_obj_document_bigint"
DO $si$
BEGIN
  CREATE INDEX IF NOT EXISTS "shares_obj_document_bigint" ON authz.shares ((object_id::bigint), relation) WHERE object_type = 'document';
EXCEPTION WHEN invalid_text_representation THEN
  RAISE EXCEPTION '%: shares of document whose ids a bigint can''t read were deleted, but a transaction open since before still sees them, and so does the index applying makes of their ids: apply again once it ends, as rowstile help AZ627 says [AZ627]', 'line 10';
END $si$;

-- A TRUNCATE empties the tables it names and, without ONLY, the tables under them, and Postgres runs the TRUNCATE
-- triggers of each (those of the audit and the feed too: CHILD_TRIGGERS). They say it once, of the table it was run
-- on: before it, each table is noted unless one above it is (p_key: the trigger function's, of the table and of those
-- under it); after it, a table noted says it, and is noted no more. (A table, not a setting: a session can't set it)
CREATE UNLOGGED TABLE authz_int.truncating (txid bigint NOT NULL, relid oid NOT NULL, key text NOT NULL,
  PRIMARY KEY (txid, relid, key));

CREATE FUNCTION authz_int.truncate_once(p_relid oid, p_key text, p_before boolean) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF NOT p_before THEN
    DELETE FROM authz_int.truncating t WHERE t.txid = txid_current() AND t.relid = p_relid AND t.key = p_key;
    RETURN FOUND;
  END IF;
  IF NOT EXISTS (WITH RECURSIVE up(oid) AS (
                   SELECT i.inhparent FROM pg_inherits i WHERE i.inhrelid = p_relid
                   UNION SELECT i.inhparent FROM pg_inherits i JOIN up ON i.inhrelid = up.oid)
                 SELECT 1 FROM authz_int.truncating t JOIN up ON t.relid = up.oid
                 WHERE t.txid = txid_current() AND t.key = p_key) THEN
    INSERT INTO authz_int.truncating VALUES (txid_current(), p_relid, p_key) ON CONFLICT DO NOTHING;
  END IF;
  RETURN false;
END $f$;

-- The feed's order: by transaction (its id), then position. A position is given when its row is written, but
-- other sessions see the row only when its transaction ends, so the feed gives only the entries of transactions
-- older than every one still open (the snapshot's xmin, in the whole server): any entry still to come is after
-- them. A long transaction holds the newest entries back until it ends.
-- Read the feed after the last entry read: SELECT * FROM authz.changes_since(authz.changes_position())
-- (administrators, sync jobs). A reader behind what authz.trim_changes() removed gets an error: it must read
-- everything again.
CREATE OR REPLACE FUNCTION authz.changes_since(p_pos bigint, p_limit int DEFAULT 1000) RETURNS SETOF authz.changes
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE
  v_to bigint := (SELECT s.value::bigint FROM authz.settings s WHERE s.key = 'changes_trimmed_to');
  v_last bigint := (SELECT s.value::bigint FROM authz.settings s WHERE s.key = 'changes_trimmed_last');
  v_xmin bigint := pg_catalog.pg_snapshot_xmin(pg_catalog.pg_current_snapshot())::text::bigint;
  v_txid bigint := (SELECT c.txid FROM authz.changes c WHERE c.pos = p_pos);
BEGIN
  IF v_txid IS NULL THEN
    -- no entry there: the feed's start, or where the trimmed part ends (every entry left comes after it)
    IF p_pos IS DISTINCT FROM coalesce(v_last, 0) THEN
      IF p_pos <= v_to THEN
        RAISE EXCEPTION 'the change feed up to position % was trimmed: read everything again, then follow from there', v_to
          USING ERRCODE = 'object_not_in_prerequisite_state', HINT = 'rowstile help AZ712';
      END IF;
      RAISE EXCEPTION 'the change feed has no entry at position %: read everything again, then follow from there', p_pos
        USING ERRCODE = 'object_not_in_prerequisite_state', HINT = 'rowstile help AZ712';
    END IF;
    v_txid := -1;
  END IF;
  RETURN QUERY SELECT * FROM authz.changes c WHERE (c.txid, c.pos) > (v_txid, p_pos) AND c.txid < v_xmin
    ORDER BY c.txid, c.pos LIMIT p_limit;
END $f$;

-- Where the feed is, for a reader that starts: the last entry it gives now (else where it was trimmed, else 0)
CREATE FUNCTION authz.changes_position() RETURNS bigint
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  SELECT coalesce(
    (SELECT c.pos FROM authz.changes c
      WHERE c.txid < pg_catalog.pg_snapshot_xmin(pg_catalog.pg_current_snapshot())::text::bigint
      ORDER BY c.txid DESC, c.pos DESC LIMIT 1),
    (SELECT s.value::bigint FROM authz.settings s WHERE s.key = 'changes_trimmed_last'), 0)
$f$;

-- Retention (both grow forever otherwise); schedule these, with pg_cron or the app's jobs.
-- The feed: entries older than p_keep, by default the setting changes_keep, else 7 days, and those before them in
-- the feed's order: what it removes is where the feed starts (changes_trimmed_last, its last entry, where a reader
-- may stand, and changes_trimmed_txid, that entry's transaction; changes_trimmed_to, the greatest position removed).
-- One trim at a time (writers go on).
CREATE OR REPLACE FUNCTION authz.trim_changes(p_keep interval DEFAULT NULL) RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE
  v_keep interval := coalesce(p_keep, (SELECT s.value::interval FROM authz.settings s WHERE s.key = 'changes_keep'),
                              interval '7 days');
  v_txid bigint; v_last bigint; v_to bigint; n bigint;
BEGIN
  LOCK TABLE authz.changes IN SHARE UPDATE EXCLUSIVE MODE;
  SELECT c.txid, c.pos INTO v_txid, v_last FROM authz.changes c
   WHERE c.at < now() - v_keep AND c.txid < pg_catalog.pg_snapshot_xmin(pg_catalog.pg_current_snapshot())::text::bigint
   ORDER BY c.txid DESC, c.pos DESC LIMIT 1;
  IF v_last IS NULL THEN RETURN 0; END IF;
  WITH d AS (DELETE FROM authz.changes c WHERE (c.txid, c.pos) <= (v_txid, v_last) RETURNING c.pos)
  SELECT count(*), max(d.pos) INTO n, v_to FROM d;
  INSERT INTO authz.settings VALUES ('changes_trimmed_to', v_to::text), ('changes_trimmed_last', v_last::text),
    ('changes_trimmed_txid', v_txid::text)
    ON CONFLICT (key) DO UPDATE SET value = CASE WHEN EXCLUDED.key = 'changes_trimmed_to'
      THEN greatest(authz.settings.value::bigint, EXCLUDED.value::bigint)::text ELSE EXCLUDED.value END;
  RETURN n;
END $f$;

-- A share ends (expires_at) or begins (starts_at) with no write to announce it: this announces the objects whose next
-- share start or end (authz.shares_due, which each share's write keeps) has passed, with the cause share_ended or
-- share_started, and what reads them; then works out each one's next. It keeps no time of its own: a clock set back
-- hides nothing. Schedule it as often as readers should hear of it; until it runs, they don't. Returns the number of
-- shares.
CREATE OR REPLACE FUNCTION authz.announce_timed_shares() RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE
  v_to timestamptz := now();
  v_due authz.shares_due[];
  n bigint;
BEGIN
  -- the objects due, locked (a writer adding a share to one locks it too): this run waits for that writer, and then
  -- reads the shares as it left them, or the writer waits for this run and then puts its share's time in
  v_due := ARRAY(SELECT d FROM authz.shares_due d WHERE d.at <= v_to ORDER BY d.object_type, d.object_id FOR UPDATE);
  PERFORM authz_int.changed(x.object_type, array_agg(x.object_id ORDER BY x.object_id), 'share_ended')
  FROM (SELECT DISTINCT d.object_type, d.object_id FROM unnest(v_due) d
        JOIN authz.shares g ON g.object_type = d.object_type AND g.object_id = d.object_id
        WHERE g.expires_at >= d.at AND g.expires_at <= v_to) x GROUP BY x.object_type;
  PERFORM authz_int.changed(x.object_type, array_agg(x.object_id ORDER BY x.object_id), 'share_started')
  FROM (SELECT DISTINCT d.object_type, d.object_id FROM unnest(v_due) d
        JOIN authz.shares g ON g.object_type = d.object_type AND g.object_id = d.object_id
        WHERE g.starts_at >= d.at AND g.starts_at <= v_to) x GROUP BY x.object_type;
  SELECT count(*) INTO n FROM unnest(v_due) d
  JOIN authz.shares g ON g.object_type = d.object_type AND g.object_id = d.object_id
  WHERE (g.expires_at >= d.at AND g.expires_at <= v_to) OR (g.starts_at >= d.at AND g.starts_at <= v_to);
  -- each one's next start or end, or none
  WITH nx AS MATERIALIZED (
    SELECT d.object_type, d.object_id,
           (SELECT min(v.at) FROM authz.shares g CROSS JOIN LATERAL (VALUES (g.starts_at), (g.expires_at)) v(at)
            WHERE g.object_type = d.object_type AND g.object_id = d.object_id AND v.at > v_to) AS at
    FROM unnest(v_due) d),
  gone AS (DELETE FROM authz.shares_due d USING nx
           WHERE nx.at IS NULL AND d.object_type = nx.object_type AND d.object_id = nx.object_id RETURNING 1)
  UPDATE authz.shares_due d SET at = nx.at FROM nx
  WHERE nx.at IS NOT NULL AND d.object_type = nx.object_type AND d.object_id = nx.object_id;
  RETURN n;
END $f$;

-- shares and role assignments
CREATE OR REPLACE FUNCTION authz_int.on_share() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE r authz.shares;
BEGIN
  r := CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  PERFORM authz_int.audit(CASE TG_OP WHEN 'INSERT' THEN 'share' WHEN 'DELETE' THEN 'unshare' ELSE 'share_changed' END,
    r.object_type, r.object_id, r.relation, r.subject_type,
    CASE WHEN r.subject_type = 'link' THEN '(link)' ELSE r.subject_id END, r.subject_relation,
    jsonb_strip_nulls(jsonb_build_object('expires_at', r.expires_at, 'starts_at', r.starts_at, 'caveat', r.caveat,
                                         'created_by', r.created_by,
                                         -- a change: what the share was (whose, of what, its times)
                                         'was', CASE WHEN TG_OP = 'UPDATE' THEN jsonb_build_object(
                                           'object_type', OLD.object_type, 'object_id', OLD.object_id,
                                           'relation', OLD.relation, 'subject_type', OLD.subject_type,
                                           'subject_id', CASE WHEN OLD.subject_type = 'link' THEN '(link)' ELSE OLD.subject_id END,
                                           'subject_relation', OLD.subject_relation, 'expires_at', OLD.expires_at,
                                           'starts_at', OLD.starts_at, 'caveat', OLD.caveat) END)));
  PERFORM authz_int.changed(r.object_type, ARRAY[r.object_id], 'share');
  -- a share that starts or ends from now on: its object's next such time, for authz.announce_timed_shares() (the
  -- earliest of what the writers put in, each locking the object's row: none is lost; a run works out the next)
  IF TG_OP <> 'DELETE' AND (NEW.starts_at >= now() OR NEW.expires_at >= now()) THEN
    INSERT INTO authz.shares_due AS d
    VALUES (NEW.object_type, NEW.object_id, least(CASE WHEN NEW.starts_at >= now() THEN NEW.starts_at END,
                                                   CASE WHEN NEW.expires_at >= now() THEN NEW.expires_at END))
    ON CONFLICT (object_type, object_id) DO UPDATE SET at = least(d.at, EXCLUDED.at);
  END IF;
  IF TG_OP = 'UPDATE' AND (OLD.object_type, OLD.object_id) IS DISTINCT FROM (NEW.object_type, NEW.object_id) THEN
    PERFORM authz_int.changed(OLD.object_type, ARRAY[OLD.object_id], 'share');
  END IF;
  RETURN NULL;
END $f$;

CREATE OR REPLACE FUNCTION authz_int.on_role() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF TG_TABLE_NAME = 'roles' THEN
    PERFORM authz_int.audit(lower(TG_OP) || '_role', CASE WHEN TG_OP = 'DELETE' THEN OLD.owner_type ELSE NEW.owner_type END,
      CASE WHEN TG_OP = 'DELETE' THEN OLD.owner_id ELSE NEW.owner_id END, NULL, NULL, NULL, NULL,
      to_jsonb(CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END));
  ELSE
    -- (a change: the permission it gave removed, the one it gives added)
    IF TG_OP IN ('DELETE', 'UPDATE') THEN
      PERFORM authz_int.audit('role_permission_removed', NULL, NULL, 'role:' || OLD.role_id, NULL, NULL, NULL,
        jsonb_build_object('permission', OLD.permission));
    END IF;
    IF TG_OP IN ('INSERT', 'UPDATE') THEN
      PERFORM authz_int.audit('role_permission_added', NULL, NULL, 'role:' || NEW.role_id, NULL, NULL, NULL,
        jsonb_build_object('permission', NEW.permission));
    END IF;
  END IF;
  RETURN NULL;
END $f$;

CREATE TRIGGER authz_role_perm_audit_upd AFTER UPDATE ON authz.role_permissions
  FOR EACH ROW WHEN (OLD IS DISTINCT FROM NEW) EXECUTE FUNCTION authz_int.on_role();

-- a role that gives more or less: the objects it is given on (its assignments are shares, 'role:<id>'; a change:
-- the roles it was in and is in)
CREATE OR REPLACE FUNCTION authz_int.on_role_permissions() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    PERFORM authz_int.changed(g.object_type, array_agg(DISTINCT g.object_id), 'role')
    FROM authz.shares g WHERE g.relation IN (SELECT 'role:' || r.role_id FROM role_rows r
                                             UNION SELECT 'role:' || n.role_id FROM new_role_rows n) GROUP BY g.object_type;
  ELSE
    PERFORM authz_int.changed(g.object_type, array_agg(DISTINCT g.object_id), 'role')
    FROM authz.shares g WHERE g.relation IN (SELECT 'role:' || r.role_id FROM role_rows r) GROUP BY g.object_type;
  END IF;
  RETURN NULL;
END $f$;

CREATE TRIGGER authz_role_perm_feed_upd AFTER UPDATE ON authz.role_permissions
  REFERENCING OLD TABLE AS role_rows NEW TABLE AS new_role_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int.on_role_permissions();

-- shares on user rows that are gone, or whose id changed, are removed (and their marks: forget_marks), and
-- the pending requests naming them are cancelled (requests_gone)
CREATE OR REPLACE FUNCTION authz_int."user__forget"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE v_gone text[];
BEGIN
  IF TG_OP = 'TRUNCATE' AND NOT EXISTS (SELECT 1 FROM "app"."users") THEN   -- the table is empty, and so are those under it
    DELETE FROM authz.shares WHERE object_type = 'user';
    DELETE FROM authz.shares WHERE subject_type = 'user' AND subject_id <> '*';      -- '*' (every one signed in) names no row
    DELETE FROM authz_int.row_marks WHERE type = 'user';
    PERFORM authz_int.requests_gone('user', NULL);
  ELSIF TG_OP = 'TRUNCATE' THEN   -- TRUNCATE ONLY, or of a table under it: some rows are still there. What named a
    -- row that is gone goes (the pending requests naming one were cancelled before, while it was there to tell)
    v_gone := ARRAY(SELECT g.id FROM (SELECT s.object_id FROM authz.shares s WHERE s.object_type = 'user'
                                      UNION SELECT s.subject_id FROM authz.shares s WHERE s.subject_type = 'user' AND s.subject_id <> '*'
                                      UNION SELECT m.id FROM authz_int.row_marks m WHERE m.type = 'user') g(id)
                    WHERE NOT EXISTS (SELECT 1 FROM "app"."users" x WHERE x."id"::text = g.id));
    PERFORM authz_int.forget_marks('user', v_gone);
    DELETE FROM authz.shares WHERE object_type = 'user' AND object_id = ANY (v_gone);
    DELETE FROM authz.shares WHERE subject_type = 'user' AND subject_id = ANY (v_gone);
  ELSIF TG_OP = 'UPDATE' THEN   -- on a partitioned table (the last trigger below): the ids the update left no row with
    PERFORM authz_int.forget_marks('user', ARRAY(SELECT o."id"::text FROM old_rows o EXCEPT SELECT n."id"::text FROM new_rows n));
    DELETE FROM authz.shares WHERE object_type = 'user' AND object_id IN (SELECT o."id"::text FROM old_rows o EXCEPT SELECT n."id"::text FROM new_rows n);
    DELETE FROM authz.shares WHERE subject_type = 'user' AND subject_id IN (SELECT o."id"::text FROM old_rows o EXCEPT SELECT n."id"::text FROM new_rows n);
    PERFORM authz_int.requests_gone('user', ARRAY(SELECT o."id"::text FROM old_rows o EXCEPT SELECT n."id"::text FROM new_rows n));
  ELSE
    PERFORM authz_int.forget_marks('user', ARRAY(SELECT o."id"::text FROM old_rows o));
    DELETE FROM authz.shares WHERE object_type = 'user' AND object_id IN (SELECT o."id"::text FROM old_rows o);
    DELETE FROM authz.shares WHERE subject_type = 'user' AND subject_id IN (SELECT o."id"::text FROM old_rows o);
    PERFORM authz_int.requests_gone('user', ARRAY(SELECT o."id"::text FROM old_rows o));
  END IF;
  RETURN NULL;
END $f$;

-- before TRUNCATE empties the table, or one under it (each has this trigger: CHILD_TRIGGERS): with a snapshot older
-- than a share on one of the rows stored there, fail to serialize. And where tables inherit from the type's, the
-- pending requests naming a row stored in the one emptied, and in no other, are cancelled: TRUNCATE ONLY, or of a
-- table under it, empties one alone, and after it a request for no row can't be told from one whose row went (a
-- request for a missing object is kept pending, so that asking doesn't tell which hidden ones exist)
CREATE OR REPLACE FUNCTION authz_int."user__forget_all"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE v_emptied text; v_ids text[];
BEGIN
  v_emptied := pg_catalog.quote_ident(TG_TABLE_SCHEMA) || '.' || pg_catalog.quote_ident(TG_TABLE_NAME);
  IF pg_catalog.current_setting('transaction_isolation') <> 'read committed' THEN
    EXECUTE $q$SELECT ARRAY(SELECT x."id"::text FROM ONLY $q$ || v_emptied || $q$ x)$q$ INTO v_ids;
    PERFORM authz_int.forget_marks('user', v_ids);
  END IF;
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_inherits i WHERE i.inhparent = '"app"."users"'::pg_catalog.regclass) THEN
    EXECUTE $q$SELECT ARRAY(SELECT g.id FROM (SELECT r.object_id FROM authz.requests r WHERE r.status = 'pending' AND r.object_type = 'user' UNION SELECT r.requester FROM authz.requests r WHERE r.status = 'pending') g(id)
      WHERE EXISTS (SELECT 1 FROM ONLY $q$ || v_emptied || $q$ x WHERE x."id"::text = g.id)
        AND NOT EXISTS (SELECT 1 FROM "app"."users" y WHERE y.tableoid <> $1 AND y."id"::text = g.id))$q$
      INTO v_ids USING TG_RELID;
    PERFORM authz_int.requests_gone('user', v_ids);
  END IF;
  RETURN NULL;
END $f$;

CREATE TRIGGER "authz_user_forget_trunc" AFTER TRUNCATE ON "app"."users"
  FOR EACH STATEMENT EXECUTE FUNCTION authz_int."user__forget"();
COMMENT ON TRIGGER "authz_user_forget_trunc" ON "app"."users" IS 'rowstile: for a TRUNCATE of the tables under its table too';

CREATE TRIGGER "authz_user_forget_trunc_first" BEFORE TRUNCATE ON "app"."users"
  FOR EACH STATEMENT EXECUTE FUNCTION authz_int."user__forget_all"();
COMMENT ON TRIGGER "authz_user_forget_trunc_first" ON "app"."users" IS 'rowstile: for a TRUNCATE of the tables under its table too';

-- shares on team rows that are gone, or whose id changed, are removed (and their marks: forget_marks), and
-- the pending requests naming them are cancelled (requests_gone)
CREATE OR REPLACE FUNCTION authz_int."team__forget"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE v_gone text[];
BEGIN
  IF TG_OP = 'TRUNCATE' AND NOT EXISTS (SELECT 1 FROM "app"."teams") THEN   -- the table is empty, and so are those under it
    DELETE FROM authz.shares WHERE object_type = 'team';
    DELETE FROM authz.shares WHERE subject_type = 'team' AND subject_id <> '*';      -- '*' (every one signed in) names no row
    DELETE FROM authz_int.row_marks WHERE type = 'team';
    PERFORM authz_int.requests_gone('team', NULL);
  ELSIF TG_OP = 'TRUNCATE' THEN   -- TRUNCATE ONLY, or of a table under it: some rows are still there. What named a
    -- row that is gone goes (the pending requests naming one were cancelled before, while it was there to tell)
    v_gone := ARRAY(SELECT g.id FROM (SELECT s.object_id FROM authz.shares s WHERE s.object_type = 'team'
                                      UNION SELECT s.subject_id FROM authz.shares s WHERE s.subject_type = 'team' AND s.subject_id <> '*'
                                      UNION SELECT m.id FROM authz_int.row_marks m WHERE m.type = 'team') g(id)
                    WHERE NOT EXISTS (SELECT 1 FROM "app"."teams" x WHERE x."id"::text = g.id));
    PERFORM authz_int.forget_marks('team', v_gone);
    DELETE FROM authz.shares WHERE object_type = 'team' AND object_id = ANY (v_gone);
    DELETE FROM authz.shares WHERE subject_type = 'team' AND subject_id = ANY (v_gone);
  ELSIF TG_OP = 'UPDATE' THEN   -- on a partitioned table (the last trigger below): the ids the update left no row with
    PERFORM authz_int.forget_marks('team', ARRAY(SELECT o."id"::text FROM old_rows o EXCEPT SELECT n."id"::text FROM new_rows n));
    DELETE FROM authz.shares WHERE object_type = 'team' AND object_id IN (SELECT o."id"::text FROM old_rows o EXCEPT SELECT n."id"::text FROM new_rows n);
    DELETE FROM authz.shares WHERE subject_type = 'team' AND subject_id IN (SELECT o."id"::text FROM old_rows o EXCEPT SELECT n."id"::text FROM new_rows n);
    PERFORM authz_int.requests_gone('team', ARRAY(SELECT o."id"::text FROM old_rows o EXCEPT SELECT n."id"::text FROM new_rows n));
  ELSE
    PERFORM authz_int.forget_marks('team', ARRAY(SELECT o."id"::text FROM old_rows o));
    DELETE FROM authz.shares WHERE object_type = 'team' AND object_id IN (SELECT o."id"::text FROM old_rows o);
    DELETE FROM authz.shares WHERE subject_type = 'team' AND subject_id IN (SELECT o."id"::text FROM old_rows o);
    PERFORM authz_int.requests_gone('team', ARRAY(SELECT o."id"::text FROM old_rows o));
  END IF;
  RETURN NULL;
END $f$;

