ALTER TABLE "app"."documents" ENABLE ROW LEVEL SECURITY;

-- A permission on an object, whether the user may select its row or not: what the functions that act on the
-- object ask (sharing, roles, keys, view_as, break_glass, requests), where authz.can's answer is for rows they may see
CREATE FUNCTION authz_int.can(p_type text, p_id text, p_perm text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE v_bigint bigint;
BEGIN
  IF NOT authz_int.scope_perm(p_type, p_perm) THEN RETURN false; END IF;
  CASE p_type
    WHEN 'user' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN false; END IF;
      v_bigint := p_id::bigint;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'team' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN false; END IF;
      v_bigint := p_id::bigint;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'document' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN false; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'share' THEN RETURN EXISTS (SELECT 1 FROM "app"."documents" o WHERE o."id" = v_bigint AND (coalesce(o."owner_id" = (SELECT authz.uid()), false)));
        WHEN 'edit' THEN RETURN EXISTS (SELECT 1 FROM "app"."documents" o WHERE o."id" = v_bigint AND ((coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."document__editor" v WHERE v.id = o."id"))));
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "app"."documents" o WHERE o."id" = v_bigint AND ((coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."document__editor" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."document__viewer" v WHERE v.id = o."id"))));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    ELSE
      RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707';
  END CASE;
END $f$;

-- Check a permission from app code: SELECT authz.can('file', 11, 'edit')
-- (only objects that exist, and on a table with a select rule only rows the user may select: a row they can't see
-- reads as a missing one; plans are cached per session)
CREATE OR REPLACE FUNCTION authz.can(p_type text, p_id text, p_perm text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE v_allowed boolean; v_bigint bigint;
BEGIN
  IF current_setting('authz_debug.log_decisions', true) = 'on'
     AND current_setting('authz_debug.logging', true) IS DISTINCT FROM 'on' THEN
    -- decision log (SET authz_debug.log_decisions = on; lines go to the server log), naming who acted as the
    -- audit trail does ('42', 'service:7'; none: nobody signed in). A check answers true or false; one that raises
    -- (a type or a permission the policy doesn't have) is not logged
    PERFORM set_config('authz_debug.logging', 'on', true);
    v_allowed := authz.can(p_type, p_id, p_perm);
    PERFORM set_config('authz_debug.logging', 'off', true);
    RAISE LOG 'authz decision: user=% type=% id=% perm=% -> %',
      coalesce(to_json(authz_int.actor())::text, 'none'), to_json(p_type)::text,
      to_json(p_id)::text, to_json(p_perm)::text, v_allowed::text;
    RETURN v_allowed;
  END IF;
  IF NOT authz_int.scope_perm(p_type, p_perm) THEN RETURN false; END IF;
  CASE p_type
    WHEN 'user' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN false; END IF;
      v_bigint := p_id::bigint;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'team' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN false; END IF;
      v_bigint := p_id::bigint;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'document' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN false; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'share' THEN RETURN EXISTS (SELECT 1 FROM "app"."documents" o WHERE o."id" = v_bigint AND (coalesce(o."owner_id" = (SELECT authz.uid()), false)));
        WHEN 'edit' THEN RETURN EXISTS (SELECT 1 FROM "app"."documents" o WHERE o."id" = v_bigint AND ((coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."document__editor" v WHERE v.id = o."id"))));
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "app"."documents" o WHERE o."id" = v_bigint AND ((coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."document__editor" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."document__viewer" v WHERE v.id = o."id"))));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    ELSE
      RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707';
  END CASE;
END $f$;

-- Every object the user holds a permission on, whether they may select its row or not: what the access previews
-- (rowstile diff, the review's access, rowstile snapshot) list, run as the owner. authz.list where it is the same
CREATE FUNCTION authz_int.list(p_type text, p_perm text) RETURNS SETOF text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  IF NOT authz_int.scope_perm(p_type, p_perm) THEN RETURN; END IF;
  CASE p_type || '.' || p_perm
    WHEN NULL THEN NULL;
    ELSE
      RETURN QUERY SELECT * FROM authz.list(p_type, p_perm);
  END CASE;
END $f$;

-- Share: needs the relation's 'shared by' permission on the object, and every permission
-- the relation grants (you can't grant more than you hold); the subject must exist
CREATE OR REPLACE FUNCTION authz.share(p_type text, p_id text, p_relation text,
  p_subject_type text, p_subject_id text, p_subject_relation text DEFAULT '',
  p_expires_at timestamptz DEFAULT NULL, p_starts_at timestamptz DEFAULT NULL,
  p_caveat text DEFAULT NULL, p_caveat_args jsonb DEFAULT NULL) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_found boolean; v_key text; v_rel authz_int.shared_relations; v_need text; v_role authz.roles; v_perms text[];
BEGIN
  PERFORM authz_int.check_writable();
  p_id := authz_int.canon(p_type, p_id);
  p_subject_id := authz_int.canon(p_subject_type, p_subject_id);
  p_subject_relation := CASE WHEN p_subject_type = 'anyone' THEN '' ELSE p_subject_relation END;  -- (no anyone#...)
  IF NOT EXISTS (SELECT 1 FROM authz.principal()) THEN
    RAISE EXCEPTION 'you cannot share % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM authz_int.types t WHERE t.name = p_type) THEN
    RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707';
  END IF;
  IF NOT pg_catalog.pg_input_is_valid(p_id, (SELECT keytype FROM authz_int.types WHERE name = p_type)) THEN
    RAISE EXCEPTION 'you cannot share % %', p_type, p_id USING ERRCODE = 'insufficient_privilege',
      DETAIL = authz_int.share_why(p_type, p_id, '{}'), HINT = 'rowstile help AZ705';
  END IF;
  -- lock the object (FOR KEY SHARE): a concurrent delete waits for us, or we for it
  v_found := authz_int.hold(p_type, p_id);
  -- a caller who may share nothing on the object gets the answer a missing object gets (this same RAISE),
  -- before the subject and the relation are looked at: sharing never tells a hidden object from a missing one
  v_found := v_found AND EXISTS (
    SELECT 1 FROM (SELECT s.shared_by AS perm FROM authz_int.shared_relations s WHERE s.object_type = p_type
                   UNION SELECT 'share') x
    -- (CASE: authz_int.can raises for a permission the type doesn't have, and AND doesn't say which runs first)
    WHERE CASE WHEN EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_type AND perm = x.perm)
               THEN authz_int.can(p_type, p_id, x.perm) ELSE false END);
  IF NOT v_found THEN
    -- why, in what authz.explain tells the caller (a hidden object as a missing one): the permission sharing this
    -- relation takes (a custom role: share), or for a relation the type doesn't share, each one sharing there takes
    v_perms := CASE WHEN p_relation LIKE 'role:%' THEN ARRAY['share'] ELSE coalesce(
      nullif(ARRAY(SELECT DISTINCT s.shared_by FROM authz_int.shared_relations s
                   WHERE s.object_type = p_type AND s.relation = p_relation), '{}'),
      ARRAY(SELECT s.shared_by FROM authz_int.shared_relations s WHERE s.object_type = p_type UNION SELECT 'share')) END;
    RAISE EXCEPTION 'you cannot share % %', p_type, p_id USING ERRCODE = 'insufficient_privilege',
      DETAIL = authz_int.share_why(p_type, p_id, v_perms), HINT = 'rowstile help AZ705';
  END IF;
  v_key := authz_int.subject_key(p_subject_type, p_subject_id, p_subject_relation);
  -- the subject must exist (and is locked, like the object)
  IF v_key NOT LIKE '%:*' AND v_key NOT IN ('anyone', 'link') THEN
    IF NOT authz_int.hold(p_subject_type, p_subject_id) THEN
      RAISE EXCEPTION 'there is no % %', p_subject_type, p_subject_id USING HINT = 'rowstile help AZ708';
    END IF;
  END IF;
  IF p_relation LIKE 'role:%' THEN
    -- a custom role: its type must match, the subject must be allowed, and you must hold all it grants
    -- (FOR SHARE: a change to its permissions waits for this share, or this share for it, and weighs what it gives)
    SELECT * INTO v_role FROM authz.roles WHERE 'role:' || id = p_relation FOR SHARE;
    IF v_role.id IS NULL OR v_role.object_type <> p_type THEN
      RAISE EXCEPTION 'no role % for %', p_relation, p_type USING HINT = 'rowstile help AZ706';
    END IF;
    IF NOT authz_int.role_owned(p_type, p_id, v_role.owner_type, v_role.owner_id) THEN
      RAISE EXCEPTION 'role % belongs to % %, which doesn''t own % %', v_role.name, v_role.owner_type, v_role.owner_id,
        p_type, p_id USING HINT = 'rowstile help AZ706';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM authz_int.role_subjects WHERE object_type = p_type AND subject = v_key) THEN
      RAISE EXCEPTION 'custom roles on % cannot be given to %', p_type, v_key USING HINT = 'rowstile help AZ706';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_type AND perm = 'share')
       OR NOT authz_int.can(p_type, p_id, 'share') THEN
      RAISE EXCEPTION 'you cannot share % %', p_type, p_id USING ERRCODE = 'insufficient_privilege',
        DETAIL = authz_int.share_why(p_type, p_id, ARRAY['share']), HINT = 'rowstile help AZ705';
    END IF;
    SELECT string_agg(permission, ', ') INTO v_need FROM authz.role_permissions
    WHERE role_id = v_role.id AND NOT authz_int.can(p_type, p_id, permission);
    IF v_need IS NOT NULL THEN
      RAISE EXCEPTION 'you cannot give role % on % %: you do not hold %', v_role.name, p_type, p_id, v_need
        USING ERRCODE = 'insufficient_privilege', DETAIL = authz_int.share_why(p_type, p_id, string_to_array(v_need, ', ')),
              HINT = 'rowstile help AZ705';
    END IF;
  ELSE
    SELECT * INTO v_rel FROM authz_int.shared_relations s
    WHERE s.object_type = p_type AND s.relation = p_relation AND s.subject = v_key;
    IF v_rel.relation IS NULL THEN
      RAISE EXCEPTION 'the policy does not allow sharing %.% with %', p_type, p_relation, v_key USING HINT = 'rowstile help AZ706';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_type AND perm = v_rel.shared_by)
       OR NOT authz_int.can(p_type, p_id, v_rel.shared_by) THEN
      RAISE EXCEPTION 'you cannot share % % (needs %)', p_type, p_id, v_rel.shared_by USING ERRCODE = 'insufficient_privilege',
        DETAIL = authz_int.share_why(p_type, p_id, ARRAY[v_rel.shared_by]), HINT = 'rowstile help AZ705';
    END IF;
    SELECT string_agg(n, ', ') INTO v_need FROM unnest(v_rel.required) n WHERE NOT authz_int.can(p_type, p_id, n);
    IF v_need IS NOT NULL THEN
      RAISE EXCEPTION 'you cannot grant %.% on % %: you do not hold %', p_type, p_relation, p_type, p_id, v_need
        USING ERRCODE = 'insufficient_privilege', DETAIL = authz_int.share_why(p_type, p_id, string_to_array(v_need, ', ')),
              HINT = 'rowstile help AZ705';
    END IF;
    IF NOT authz_int.share_if(p_type || '.' || p_relation || '.' || v_key, p_id, p_subject_type,
                              p_subject_id, p_subject_relation) THEN
      RAISE EXCEPTION 'the policy does not allow this share (%)', coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = v_rel.loc), '?') USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
    END IF;
  END IF;
  IF p_caveat IS NOT NULL AND NOT EXISTS (SELECT 1 FROM authz_int.caveats WHERE name = p_caveat) THEN
    RAISE EXCEPTION 'no caveat % in the policy', p_caveat USING HINT = 'rowstile help AZ707';
  END IF;
  PERFORM authz_int.mark_row(p_type, p_id);
  IF v_key NOT LIKE '%:*' AND v_key NOT IN ('anyone', 'link') THEN
    PERFORM authz_int.mark_row(p_subject_type, p_subject_id);
  END IF;
  INSERT INTO authz.shares (object_type, object_id, relation, subject_type, subject_id, subject_relation,
                            expires_at, created_by, starts_at, caveat, caveat_args)
  VALUES (p_type, p_id, p_relation, p_subject_type, p_subject_id, p_subject_relation,
          p_expires_at, authz_int.actor(), p_starts_at, p_caveat, p_caveat_args)
  ON CONFLICT ON CONSTRAINT shares_pkey
  DO UPDATE SET expires_at = EXCLUDED.expires_at, created_by = EXCLUDED.created_by,
                starts_at = EXCLUDED.starts_at, caveat = EXCLUDED.caveat, caveat_args = EXCLUDED.caveat_args;
END $f$;

-- Unshare: needs what sharing needs (the relation's 'shared by' permission)
CREATE OR REPLACE FUNCTION authz.unshare(p_type text, p_id text, p_relation text,
  p_subject_type text, p_subject_id text, p_subject_relation text DEFAULT '') RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_by text;
BEGIN
  PERFORM authz_int.check_writable();
  p_id := authz_int.canon(p_type, p_id);
  p_subject_id := authz_int.canon(p_subject_type, p_subject_id);
  p_subject_relation := CASE WHEN p_subject_type = 'anyone' THEN '' ELSE p_subject_relation END;  -- (no anyone#...)
  v_by := coalesce(authz_int.manage_perm(p_type, p_relation,
                                         authz_int.subject_key(p_subject_type, p_subject_id, p_subject_relation)),
                   authz_int.manage_perm(p_type, p_relation));
  -- what it needs comes from the policy alone: the same words for a hidden object and a missing one
  IF NOT EXISTS (SELECT 1 FROM authz.principal()) OR v_by IS NULL
     OR NOT EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_type AND perm = v_by)
     OR NOT authz_int.can(p_type, p_id, v_by) THEN
    IF v_by IS NULL THEN
      RAISE EXCEPTION 'you cannot unshare % on % %', p_relation, p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
    END IF;
    RAISE EXCEPTION 'you cannot unshare % on % % (needs %)', p_relation, p_type, p_id, v_by USING ERRCODE = 'insufficient_privilege',
      DETAIL = authz_int.share_why(p_type, p_id, ARRAY[v_by]), HINT = 'rowstile help AZ705';
  END IF;
  DELETE FROM authz.shares WHERE object_type = p_type AND object_id = p_id
    AND relation = p_relation AND subject_type = p_subject_type
    AND subject_id = p_subject_id AND subject_relation = p_subject_relation;
END $f$;

-- Custom roles: defined per owner (e.g. an org) by people with 'manage_roles' there
CREATE OR REPLACE FUNCTION authz.create_role(p_owner_type text, p_owner_id text, p_object_type text, p_name text,
  p_permissions text[]) RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_id bigint; v_bad text;
BEGIN
  PERFORM authz_int.check_writable();
  PERFORM authz_int.users_only('authz.create_role');
  p_owner_id := authz_int.canon(p_owner_type, p_owner_id);
  IF NOT EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_owner_type AND perm = 'manage_roles') THEN
    RAISE EXCEPTION '% has no manage_roles permission in the policy', p_owner_type USING HINT = 'rowstile help AZ707';
  END IF;
  -- a type without `roles` (or one the policy doesn't have): a role there would be one nobody can be given
  IF NOT EXISTS (SELECT 1 FROM authz_int.role_subjects WHERE object_type = p_object_type) THEN
    RAISE EXCEPTION 'no custom roles on % in the policy', p_object_type USING HINT = 'rowstile help AZ707';
  END IF;
  IF authz.uid() IS NULL OR NOT authz_int.can(p_owner_type, p_owner_id, 'manage_roles') THEN
    RAISE EXCEPTION 'you cannot manage roles of % %', p_owner_type, p_owner_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  IF p_owner_type IS DISTINCT FROM coalesce(authz_int.role_owner_type(p_object_type), p_owner_type) THEN
    RAISE EXCEPTION 'custom roles on % belong to a % (the policy says where they come from), not to a %',
      p_object_type, authz_int.role_owner_type(p_object_type), p_owner_type USING HINT = 'rowstile help AZ706';
  END IF;
  SELECT string_agg(p, ', ') INTO v_bad FROM unnest(p_permissions) p
  WHERE NOT EXISTS (SELECT 1 FROM authz_int.role_grantable g WHERE g.object_type = p_object_type AND g.permission = p);
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'custom roles on % cannot grant %', p_object_type, v_bad USING HINT = 'rowstile help AZ706';
  END IF;
  INSERT INTO authz.roles (owner_type, owner_id, object_type, name, created_by)
  VALUES (p_owner_type, p_owner_id, p_object_type, p_name, authz_int.actor())
  RETURNING id INTO v_id;
  INSERT INTO authz.role_permissions SELECT v_id, p FROM unnest(p_permissions) p ON CONFLICT DO NOTHING;
  RETURN v_id;
END $f$;

CREATE OR REPLACE FUNCTION authz.set_role_permissions(p_role bigint, p_permissions text[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v authz.roles; v_bad text; v_obj text; v_need text;
BEGIN
  PERFORM authz_int.check_writable();
  PERFORM authz_int.users_only('authz.set_role_permissions');
  SELECT * INTO v FROM authz.roles WHERE id = p_role;
  IF v.id IS NULL OR authz.uid() IS NULL OR NOT authz_int.can(v.owner_type, v.owner_id, 'manage_roles') THEN
    RAISE EXCEPTION 'you cannot manage role %', p_role USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  SELECT string_agg(p, ', ') INTO v_bad FROM unnest(p_permissions) p
  WHERE NOT EXISTS (SELECT 1 FROM authz_int.role_grantable g WHERE g.object_type = v.object_type AND g.permission = p);
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION 'custom roles on % cannot grant %', v.object_type, v_bad USING HINT = 'rowstile help AZ706'; END IF;
  -- each permission added must be one the caller holds on each object the role is given on (by a share not expired:
  -- an expired one gives again only through authz.share, which weighs it), as authz.share asks of whoever gives it
  -- there; removing one needs nothing more. Locked first: a share of it meanwhile waits, then weighs what it gives
  -- now. An object the caller can't see is not named (as authz.explain doesn't)
  PERFORM 1 FROM authz.roles WHERE id = p_role FOR UPDATE;
  SELECT o.id, o.need INTO v_obj, v_need
  FROM (SELECT g.id, (SELECT string_agg(p, ', ' ORDER BY p) FROM unnest(p_permissions) p
                      WHERE p NOT IN (SELECT r.permission FROM authz.role_permissions r WHERE r.role_id = p_role)
                        AND NOT authz.can(v.object_type, g.id, p)) AS need
        FROM (SELECT DISTINCT s.object_id AS id FROM authz.shares s
              WHERE s.object_type = v.object_type AND s.relation = 'role:' || p_role
                AND (s.expires_at IS NULL OR s.expires_at > now())) g) o
  WHERE o.need IS NOT NULL
  ORDER BY (authz_int.may_inspect(v.object_type, o.id) OR authz_int.visible(v.object_type, o.id)) DESC, o.id LIMIT 1;
  IF v_need IS NOT NULL THEN
    IF authz_int.may_inspect(v.object_type, v_obj) OR authz_int.visible(v.object_type, v_obj) THEN
      RAISE EXCEPTION 'you cannot give role % on % %: you do not hold %', v.name, v.object_type, v_obj, v_need
        USING ERRCODE = 'insufficient_privilege',
              DETAIL = authz_int.share_why(v.object_type, v_obj, string_to_array(v_need, ', ')), HINT = 'rowstile help AZ705';
    END IF;
    RAISE EXCEPTION 'you cannot give role % on a % you cannot see: you do not hold %', v.name, v.object_type, v_need
      USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  DELETE FROM authz.role_permissions WHERE role_id = p_role;
  INSERT INTO authz.role_permissions SELECT p_role, p FROM unnest(p_permissions) p ON CONFLICT DO NOTHING;
END $f$;

CREATE OR REPLACE FUNCTION authz.delete_role(p_role bigint) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v authz.roles;
BEGIN
  PERFORM authz_int.check_writable();
  PERFORM authz_int.users_only('authz.delete_role');
  SELECT * INTO v FROM authz.roles WHERE id = p_role;
  IF v.id IS NULL OR authz.uid() IS NULL OR NOT authz_int.can(v.owner_type, v.owner_id, 'manage_roles') THEN
    RAISE EXCEPTION 'you cannot manage role %', p_role USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  DELETE FROM authz.roles WHERE id = p_role;
END $f$;

CREATE OR REPLACE FUNCTION authz.roles_of(p_owner_type text, p_owner_id text)
RETURNS TABLE (id bigint, object_type text, name text, permissions text[])
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  PERFORM authz_int.users_only('authz.roles_of');
  p_owner_id := authz_int.canon(p_owner_type, p_owner_id);
  IF authz.uid() IS NULL OR NOT (
       (EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_owner_type AND perm = 'manage_roles')
        AND authz_int.can(p_owner_type, p_owner_id, 'manage_roles'))
    OR (EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_owner_type AND perm = 'view')
        AND authz_int.can(p_owner_type, p_owner_id, 'view'))) THEN
    RAISE EXCEPTION 'you cannot see roles of % %', p_owner_type, p_owner_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  RETURN QUERY SELECT r.id, r.object_type, r.name,
    ARRAY(SELECT p.permission FROM authz.role_permissions p WHERE p.role_id = r.id ORDER BY 1)
    FROM authz.roles r WHERE r.owner_type = p_owner_type AND r.owner_id = p_owner_id ORDER BY r.id;
END $f$;

-- Which of these people (or principals of another type) hold a permission: who to tell about a change.
-- It signs each one in as act_as does, then the caller again: so only a backend trusted to sign anyone in can
-- use it (the app role), as it could ask authz.can for each one itself. Not in a session limited by scopes or view-as. SELECT * FROM authz.who_among('chat', '7', 'read', ARRAY['1', '2'])
-- (it reads those settings as they are: the guard only keeps its last sign-in, which ends scopes and view-as, from
-- widening the session. Its sign-ins aren't held to one principal a transaction, as authz.act_as's are: it puts
-- back the caller)
CREATE OR REPLACE FUNCTION authz.who_among(p_type text, p_id text, p_perm text, p_users text[], p_principal_type text DEFAULT 'user')
RETURNS SETOF text LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_me text := nullif(current_setting('authz.user_id', true), '');
        v_pt text := coalesce(nullif(current_setting('authz.principal_type', true), ''), 'user');
        v_u text;
BEGIN
  -- (it runs as the owner: the caller's own right to sign people in is asked for)
  IF NOT has_function_privilege(authz_int.caller_role(), 'authz.act_as(text, text)', 'EXECUTE') THEN
    RAISE EXCEPTION 'permission denied for function act_as: authz.who_among() signs people in, which % may not',
      authz_int.caller_role() USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  IF coalesce(current_setting('authz.scopes', true), '') <> '' OR coalesce(current_setting('authz.acting_user', true), '') <> '' THEN
    RAISE EXCEPTION 'authz.who_among() signs people in, which a session limited by scopes or view-as may not'
      USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ704';
  END IF;
  FOREACH v_u IN ARRAY coalesce(p_users, '{}') LOOP
    PERFORM authz_int.act_as(p_principal_type, v_u, false);
    IF authz.can(p_type, p_id, p_perm) THEN RETURN NEXT v_u; END IF;
  END LOOP;
  PERFORM authz_int.act_as(v_pt, v_me, false);
END $f$;

CREATE FUNCTION authz_int."team__member__why"(p_id bigint, p_depth int, p_seen text[], p_asker text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_t record;
BEGIN
  IF p_id IN (SELECT s."team_id" AS id FROM "app"."team_members" s WHERE s."user_id" = (SELECT authz.uid())) THEN
    RETURN NEXT pad || 'yes  ' || CASE WHEN p_asker IS NULL THEN 'member: a row in app.team_members names you' ELSE 'member: a row in app.team_members names them' END || '';
    RETURN;
  END IF;
  RETURN NEXT pad || CASE WHEN p_asker IS NULL THEN 'no   you do not hold ' ELSE 'no   they do not hold ' END || 'team.member';
END $f$;

CREATE FUNCTION authz_int."document__owner__why"(p_id bigint, p_depth int, p_seen text[], p_asker text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_t record;
BEGIN
  IF p_id IN (SELECT r."id" AS id FROM "app"."documents" r WHERE r."owner_id" = (SELECT authz.uid())) THEN
    RETURN NEXT pad || 'yes  ' || CASE WHEN p_asker IS NULL THEN 'owner: owner_id is you' ELSE 'owner: owner_id is them' END || '';
    RETURN;
  END IF;
  RETURN NEXT pad || CASE WHEN p_asker IS NULL THEN 'no   you do not hold ' ELSE 'no   they do not hold ' END || 'document.owner';
END $f$;

CREATE FUNCTION authz_int."document__editor__why"(p_id bigint, p_depth int, p_seen text[], p_asker text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_t record;
BEGIN
  IF p_id IN (SELECT g.object_id::bigint AS id FROM authz.shares g WHERE g.object_type = 'document' AND g.relation = 'editor' AND g.subject_type = 'user' AND g.subject_relation = '' AND g.subject_id = (SELECT authz.uid()::text) AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL) THEN
    RETURN NEXT pad || 'yes  ' || CASE WHEN p_asker IS NULL THEN 'editor: shared with you' ELSE 'editor: shared with them' END || CASE WHEN p_asker IS NULL OR authz_int.asker_sees(p_asker, 'document', p_id::text, true) THEN coalesce((SELECT concat(' (by ', coalesce(g.created_by, 'an admin'), coalesce(', until ' || g.expires_at, ''), coalesce(', from ' || g.starts_at, ''), coalesce(', caveat ' || g.caveat, ''), ')') FROM authz.shares g WHERE g.object_type = 'document' AND g.object_id = p_id::text AND g.relation = 'editor' AND g.subject_type = 'user' AND g.subject_relation = '' AND g.subject_id = (SELECT authz.uid()::text) AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL ORDER BY g.created_at LIMIT 1), '') ELSE '' END;
    RETURN;
  END IF;
  IF p_id IN (SELECT g.object_id::bigint AS id FROM authz.shares g WHERE g.object_type = 'document' AND g.relation = 'editor' AND g.subject_type = 'team' AND g.subject_relation = 'member' AND g.subject_id IN (SELECT id::text FROM authz_int."team__member") AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL) THEN
    FOR v_t IN SELECT x.gid::text AS gid FROM (SELECT g.subject_id AS gid FROM authz.shares g WHERE g.object_type = 'document' AND g.object_id = p_id::text AND g.relation = 'editor' AND g.subject_type = 'team' AND g.subject_relation = 'member' AND g.subject_id IN (SELECT id::text FROM authz_int."team__member") AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL) x LIMIT 1 LOOP
      IF p_asker IS NOT NULL AND NOT authz_int.asker_sees(p_asker, 'team', v_t.gid, false) THEN
        RETURN NEXT pad || 'yes  ' || 'editor: shared with' || ' a team you can''t see';
        RETURN;
      END IF;
      RETURN NEXT pad || 'yes  ' || 'editor: shared with' || ' team ' || v_t.gid || CASE WHEN p_asker IS NULL THEN ', and you are member there' ELSE ', and they are member there' END;
      RETURN QUERY SELECT * FROM authz_int."team__member__why"(v_t.gid::bigint, p_depth + 1, p_seen, p_asker);
    END LOOP;
    RETURN;
  END IF;
  RETURN NEXT pad || CASE WHEN p_asker IS NULL THEN 'no   you do not hold ' ELSE 'no   they do not hold ' END || 'document.editor';
END $f$;

CREATE FUNCTION authz_int."document__viewer__why"(p_id bigint, p_depth int, p_seen text[], p_asker text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_t record;
BEGIN
  IF p_id IN (SELECT g.object_id::bigint AS id FROM authz.shares g WHERE g.object_type = 'document' AND g.relation = 'viewer' AND g.subject_type = 'user' AND g.subject_relation = '' AND g.subject_id = (SELECT authz.uid()::text) AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL) THEN
    RETURN NEXT pad || 'yes  ' || CASE WHEN p_asker IS NULL THEN 'viewer: shared with you' ELSE 'viewer: shared with them' END || CASE WHEN p_asker IS NULL OR authz_int.asker_sees(p_asker, 'document', p_id::text, true) THEN coalesce((SELECT concat(' (by ', coalesce(g.created_by, 'an admin'), coalesce(', until ' || g.expires_at, ''), coalesce(', from ' || g.starts_at, ''), coalesce(', caveat ' || g.caveat, ''), ')') FROM authz.shares g WHERE g.object_type = 'document' AND g.object_id = p_id::text AND g.relation = 'viewer' AND g.subject_type = 'user' AND g.subject_relation = '' AND g.subject_id = (SELECT authz.uid()::text) AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL ORDER BY g.created_at LIMIT 1), '') ELSE '' END;
    RETURN;
  END IF;
  IF p_id IN (SELECT g.object_id::bigint AS id FROM authz.shares g WHERE g.object_type = 'document' AND g.relation = 'viewer' AND g.subject_type = 'team' AND g.subject_relation = 'member' AND g.subject_id IN (SELECT id::text FROM authz_int."team__member") AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL) THEN
    FOR v_t IN SELECT x.gid::text AS gid FROM (SELECT g.subject_id AS gid FROM authz.shares g WHERE g.object_type = 'document' AND g.object_id = p_id::text AND g.relation = 'viewer' AND g.subject_type = 'team' AND g.subject_relation = 'member' AND g.subject_id IN (SELECT id::text FROM authz_int."team__member") AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL) x LIMIT 1 LOOP
      IF p_asker IS NOT NULL AND NOT authz_int.asker_sees(p_asker, 'team', v_t.gid, false) THEN
        RETURN NEXT pad || 'yes  ' || 'viewer: shared with' || ' a team you can''t see';
        RETURN;
      END IF;
      RETURN NEXT pad || 'yes  ' || 'viewer: shared with' || ' team ' || v_t.gid || CASE WHEN p_asker IS NULL THEN ', and you are member there' ELSE ', and they are member there' END;
      RETURN QUERY SELECT * FROM authz_int."team__member__why"(v_t.gid::bigint, p_depth + 1, p_seen, p_asker);
    END LOOP;
    RETURN;
  END IF;
  RETURN NEXT pad || CASE WHEN p_asker IS NULL THEN 'no   you do not hold ' ELSE 'no   they do not hold ' END || 'document.viewer';
END $f$;

CREATE FUNCTION authz_int."document__share__why"(p_id bigint, p_depth int, p_seen text[], p_asker text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."document__share");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  RETURN NEXT pad || 'document.share = owner';
  BEGIN
    v_ok := (p_id) IN (SELECT id FROM authz_int."document__owner");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'owner';
    IF v_ok AND NOT v_done THEN v_done := true; RETURN QUERY SELECT * FROM authz_int."document__owner__why"(p_id, p_depth + 1, p_seen, p_asker); END IF;
  END;
END $f$;

CREATE FUNCTION authz_int."document__edit__why"(p_id bigint, p_depth int, p_seen text[], p_asker text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."document__edit");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  RETURN NEXT pad || 'document.edit = share or editor';
  BEGIN
    v_ok := (p_id) IN (SELECT id FROM authz_int."document__share");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'share';
    IF v_ok AND NOT v_done THEN v_done := true; RETURN QUERY SELECT * FROM authz_int."document__share__why"(p_id, p_depth + 1, p_seen, p_asker); END IF;
    v_ok := (p_id) IN (SELECT id FROM authz_int."document__editor");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'editor';
    IF v_ok AND NOT v_done THEN v_done := true; RETURN QUERY SELECT * FROM authz_int."document__editor__why"(p_id, p_depth + 1, p_seen, p_asker); END IF;
  END;
END $f$;

CREATE FUNCTION authz_int."document__view__why"(p_id bigint, p_depth int, p_seen text[], p_asker text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."document__view");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  RETURN NEXT pad || 'document.view = edit or viewer';
  BEGIN
    v_ok := (p_id) IN (SELECT id FROM authz_int."document__edit");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'edit';
    IF v_ok AND NOT v_done THEN v_done := true; RETURN QUERY SELECT * FROM authz_int."document__edit__why"(p_id, p_depth + 1, p_seen, p_asker); END IF;
    v_ok := (p_id) IN (SELECT id FROM authz_int."document__viewer");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'viewer';
    IF v_ok AND NOT v_done THEN v_done := true; RETURN QUERY SELECT * FROM authz_int."document__viewer__why"(p_id, p_depth + 1, p_seen, p_asker); END IF;
  END;
END $f$;

-- What explain may show of an object while it walks as another user (p_asker: the one asking, as user id,
-- principal type and scopes; NULL: they ask of themselves): whether the one asking sees it or, p_inspect, may inspect
-- it (list its shares). It asks as them, then puts back the user explained.
CREATE FUNCTION authz_int.asker_sees(p_asker text[], p_type text, p_id text, p_inspect boolean) RETURNS boolean
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_user text := coalesce(current_setting('authz.user_id', true), '');
        v_pt text := coalesce(current_setting('authz.principal_type', true), '');
        v_scopes text := coalesce(current_setting('authz.scopes', true), ''); v_ok boolean;
BEGIN
  IF p_asker IS NULL THEN RETURN authz_int.visible(p_type, p_id); END IF;   -- (asked only whether they see it)
  IF authz_int.caller_is_admin() THEN RETURN true; END IF;
  PERFORM set_config('authz.user_id', p_asker[1], true);
  PERFORM set_config('authz.principal_type', p_asker[2], true);
  PERFORM set_config('authz.scopes', p_asker[3], true);
  PERFORM authz_int.sign();
  v_ok := CASE WHEN p_inspect THEN authz_int.may_inspect(p_type, p_id) ELSE authz_int.visible(p_type, p_id) END;
  PERFORM set_config('authz.user_id', v_user, true);
  PERFORM set_config('authz.principal_type', v_pt, true);
  PERFORM set_config('authz.scopes', v_scopes, true);
  PERFORM authz_int.sign();
  RETURN v_ok;
END $f$;

-- Everyone who holds a permission on an object: SELECT * FROM authz.who('folder', 3, 'view')
-- Candidates come from the data (a superset); each is checked as that user (the permission itself, authz_int.can).
CREATE OR REPLACE FUNCTION authz.who(p_type text, p_id text, p_perm text) RETURNS SETOF text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_me text := coalesce(current_setting('authz.user_id', true), ''); v_c text;
        v_pt text := coalesce(current_setting('authz.principal_type', true), '');
        v_scopes text := coalesce(current_setting('authz.scopes', true), ''); v_bigint bigint;
BEGIN
  IF NOT authz_int.may_inspect(p_type, p_id) OR NOT authz_int.scope_perm(p_type, p_perm) THEN
    RAISE EXCEPTION 'you cannot see who has access to % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  -- (the caller's settings are put back below; an error needs nothing put back: Postgres undoes these settings with
  -- the transaction, or the savepoint the error is caught at, as for explain, check_invariants and the logins)
  PERFORM set_config('authz.scopes', '', true);   -- each candidate is checked with full rights
  PERFORM set_config('authz.principal_type', '', true);   -- candidates are users
  <<asking>> BEGIN
  CASE p_type
    WHEN 'user' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN EXIT asking; END IF;
      v_bigint := p_id::bigint;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'team' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN EXIT asking; END IF;
      v_bigint := p_id::bigint;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'document' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN EXIT asking; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'share' THEN
          FOR v_c IN SELECT DISTINCT x::text FROM authz_int."document__share__who"(v_bigint) x WHERE EXISTS (SELECT 1 FROM "app"."users" u WHERE u."id" = x) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'edit' THEN
          FOR v_c IN SELECT DISTINCT x::text FROM authz_int."document__edit__who"(v_bigint) x WHERE EXISTS (SELECT 1 FROM "app"."users" u WHERE u."id" = x) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'view' THEN
          FOR v_c IN SELECT DISTINCT x::text FROM authz_int."document__view__who"(v_bigint) x WHERE EXISTS (SELECT 1 FROM "app"."users" u WHERE u."id" = x) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    ELSE
      RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707';
  END CASE;
  END asking;
  PERFORM set_config('authz.user_id', v_me, true);
  PERFORM set_config('authz.principal_type', v_pt, true);
  PERFORM set_config('authz.scopes', v_scopes, true);
  PERFORM authz_int.sign();
END $f$;

-- Why the current user (or, for people who may inspect the object, another user) holds a
-- permission, or what is missing: SELECT * FROM authz.explain('file', 11, 'edit')
CREATE OR REPLACE FUNCTION authz.explain(p_type text, p_id text, p_perm text, p_user text DEFAULT NULL) RETURNS SETOF text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_me text := coalesce(current_setting('authz.user_id', true), ''); v_ok boolean; v_bigint bigint;
        v_pt text := coalesce(current_setting('authz.principal_type', true), '');
        v_scopes text := coalesce(current_setting('authz.scopes', true), '');
        v_asker text[];   -- for another user: the one asking, whose sight the walk keeps to
BEGIN
  -- the signed-in user's own id is the signed-in user: asked as without it (a service whose id is a user's is not)
  IF p_user IS NOT NULL AND authz_int.canon('user', p_user) IS NOT DISTINCT FROM authz.uid()::text THEN
    p_user := NULL;
  END IF;
  -- another user's access: only for people who may inspect the object, within their scopes (as authz.who)
  IF p_user IS NOT NULL AND (NOT authz_int.may_inspect(p_type, p_id) OR NOT authz_int.scope_perm(p_type, p_perm)) THEN
    RAISE EXCEPTION 'you cannot inspect access to % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  -- people who can't see the object learn nothing about it, whatever else they hold on it (as for a missing one)
  IF p_user IS NULL AND NOT authz_int.may_inspect(p_type, p_id) AND NOT authz_int.visible(p_type, p_id) THEN
    RETURN NEXT 'no   you have no access to ' || p_type || ' ' || p_id;
    RETURN;
  END IF;
  IF p_user IS NOT NULL THEN
    v_asker := ARRAY[v_me, v_pt, v_scopes];
    PERFORM set_config('authz.user_id', authz_int.canon('user', p_user), true);
    PERFORM set_config('authz.principal_type', '', true);
    PERFORM set_config('authz.scopes', '', true);   -- that user's access, with full rights (as authz.who)
    PERFORM authz_int.sign();
  END IF;
  v_ok := authz_int.can(p_type, p_id, p_perm);
  RETURN NEXT CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || coalesce(coalesce(nullif(current_setting('authz.principal_type', true), ''), 'user') || ' ' || nullif(current_setting('authz.user_id', true), ''), 'nobody')
    || ' ' || CASE WHEN v_ok THEN 'holds ' ELSE 'does not hold ' END || p_perm || ' on ' || p_type || ' ' || p_id;
  <<asking>> BEGIN
  CASE p_type
    WHEN 'user' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN EXIT asking; END IF;
      v_bigint := p_id::bigint;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'team' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN EXIT asking; END IF;
      v_bigint := p_id::bigint;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'document' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN EXIT asking; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'share' THEN RETURN QUERY SELECT * FROM authz_int."document__share__why"(v_bigint, 1, '{}', v_asker);
        WHEN 'edit' THEN RETURN QUERY SELECT * FROM authz_int."document__edit__why"(v_bigint, 1, '{}', v_asker);
        WHEN 'view' THEN RETURN QUERY SELECT * FROM authz_int."document__view__why"(v_bigint, 1, '{}', v_asker);
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    ELSE
      RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707';
  END CASE;
  END asking;
  PERFORM set_config('authz.user_id', v_me, true);
  PERFORM set_config('authz.principal_type', v_pt, true);
  PERFORM set_config('authz.scopes', v_scopes, true);
  PERFORM authz_int.sign();
END $f$;

-- the keys of principals that are gone, or whose id changed (p_ids; NULL: every one of the type, TRUNCATE) are
-- deleted, each in the audit trail, with the rows' marks (forget_marks: in a transaction whose snapshot may be older
-- than a key made for one of them, that fails to serialize, 40001)
CREATE OR REPLACE FUNCTION authz_int.keys_gone(p_type text, p_ids text[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE k record;
BEGIN
  IF p_ids IS NULL THEN
    DELETE FROM authz_int.row_marks WHERE type = p_type;
  ELSE
    PERFORM authz_int.forget_marks(p_type, p_ids);
  END IF;
  -- (by api_keys_by_principal: one lookup for each id, or for the type)
  FOR k IN DELETE FROM authz.api_keys WHERE principal_type = p_type AND p_ids IS NULL
           RETURNING id, user_id, name LOOP
    PERFORM authz_int.audit('delete_api_key', p_type, k.user_id, NULL, NULL, NULL, NULL,
                            jsonb_build_object('key', k.id, 'name', k.name, 'why', 'its principal is gone'));
  END LOOP;
  FOR k IN DELETE FROM authz.api_keys WHERE principal_type = p_type AND user_id = ANY (p_ids)
           RETURNING id, user_id, name LOOP
    PERFORM authz_int.audit('delete_api_key', p_type, k.user_id, NULL, NULL, NULL, NULL,
                            jsonb_build_object('key', k.id, 'name', k.name, 'why', 'its principal is gone'));
  END LOOP;
END $f$;

-- API keys: a signed-in user's own, or a principal's (a service's) made by someone holding
-- manage_keys on it; only a hash is kept
CREATE OR REPLACE FUNCTION authz.create_api_key(p_name text, p_scopes text DEFAULT '', p_expires_at timestamptz DEFAULT NULL,
  p_principal_type text DEFAULT NULL, p_principal_id text DEFAULT NULL)
RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_token text := 'ak_' || replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');
        v_scopes text[] := ARRAY(SELECT DISTINCT btrim(x) FROM unnest(string_to_array(coalesce(p_scopes, ''), ',')) x
                                 WHERE btrim(x) <> '' ORDER BY 1);
        v_cur text[] := authz_int.scopes_active(); v_bad text;
        v_type text := coalesce(p_principal_type, 'user'); v_id text;
BEGIN
  PERFORM authz_int.check_writable();
  IF coalesce(btrim(p_name), '') = '' THEN
    RAISE EXCEPTION 'name the key (its name says what it is for)' USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  PERFORM authz_int.key_owner_given(p_principal_type, p_principal_id);
  -- the principal's row is locked (FOR KEY SHARE) before it is checked: a delete of it waits for this key, or this
  -- for the delete, which leaves no principal to make it for (a delete with an older snapshot: keys_gone)
  IF p_principal_id IS NULL THEN
    PERFORM authz_int.users_only('authz.create_api_key for oneself');
    v_id := authz.uid()::text;
    IF v_type <> 'user' OR v_id IS NULL OR NOT authz_int.hold('user', v_id) THEN
      RAISE EXCEPTION 'sign in to create an API key' USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ714';
    END IF;
  ELSE
    v_id := authz_int.canon(v_type, p_principal_id);
    -- (no row there: authz.can holds only on rows that are, so the check refuses it, as one you can't manage)
    PERFORM authz_int.hold(v_type, v_id);
    PERFORM authz_int.check_manage_keys(v_type, v_id);
  END IF;
  SELECT string_agg(x, ', ') INTO v_bad FROM unnest(v_scopes) x
  WHERE NOT EXISTS (SELECT 1 FROM authz_int.scope_items WHERE scope = x);
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION 'no scope % in the policy', v_bad USING HINT = 'rowstile help AZ707'; END IF;
  IF v_cur IS NOT NULL AND (cardinality(v_scopes) = 0 OR NOT v_scopes <@ v_cur) THEN
    RAISE EXCEPTION 'a key cannot have more scopes than the session creating it' USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ704';
  END IF;
  INSERT INTO authz.api_keys (user_id, principal_type, name, prefix, hash, scopes, expires_at)
  VALUES (v_id, v_type, p_name, left(v_token, 10), encode(sha256(convert_to(v_token, 'UTF8')), 'hex'),
          array_to_string(v_scopes, ','), p_expires_at);
  PERFORM authz_int.mark_row(v_type, v_id);
  PERFORM authz_int.audit('create_api_key', v_type, v_id, NULL, NULL, NULL, NULL,
                          jsonb_build_object('name', p_name, 'scopes', v_scopes, 'expires_at', p_expires_at));
  RETURN v_token;
END $f$;

-- A principal's keys are named by its type and its id; a type without an id is a mistake, not one's own keys
CREATE FUNCTION authz_int.key_owner_given(p_type text, p_id text) RETURNS void
LANGUAGE plpgsql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF p_id IS NULL AND coalesce(p_type, 'user') <> 'user' THEN
    RAISE EXCEPTION 'a key for % needs its id too (give neither for your own keys)', p_type
      USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
END $f$;

-- May the signed-in principal manage the keys of this one? Needs `can manage_keys` on its type.
CREATE OR REPLACE FUNCTION authz_int.check_manage_keys(p_type text, p_id text) RETURNS void
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM authz_int.types WHERE name = p_type AND principal) THEN
    RAISE EXCEPTION 'no type % that signs in (type ... principal) in the policy', p_type USING HINT = 'rowstile help AZ707';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_type AND perm = 'manage_keys') THEN
    RAISE EXCEPTION 'the policy gives % no manage_keys permission, so nobody manages its keys', p_type
      USING HINT = 'rowstile help AZ707';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM authz.principal()) OR NOT coalesce(authz_int.can(p_type, p_id, 'manage_keys'), false) THEN
    RAISE EXCEPTION 'you cannot manage the keys of % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
END $f$;

-- Your keys, or (with manage_keys on it) a principal's
CREATE OR REPLACE FUNCTION authz.list_api_keys(p_principal_type text DEFAULT NULL, p_principal_id text DEFAULT NULL)
RETURNS TABLE (id bigint, name text, prefix text, scopes text, created_at timestamptz, expires_at timestamptz,
               last_used_at timestamptz, revoked_at timestamptz)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_type text; v_id text;
BEGIN
  PERFORM authz_int.key_owner_given(p_principal_type, p_principal_id);
  IF p_principal_id IS NULL THEN
    SELECT p.principal_type, p.principal_id INTO v_type, v_id FROM authz.principal() p;
  ELSE
    v_type := coalesce(p_principal_type, 'user');
    v_id := authz_int.canon(v_type, p_principal_id);
    PERFORM authz_int.check_manage_keys(v_type, v_id);
  END IF;
  RETURN QUERY SELECT k.id, k.name, k.prefix, k.scopes, k.created_at, k.expires_at, k.last_used_at, k.revoked_at
  FROM authz.api_keys k WHERE k.user_id = v_id AND k.principal_type = v_type ORDER BY k.id;
END $f$;

-- Revoke a key: your own, a user's you may inspect, or a principal's you manage the keys of
CREATE OR REPLACE FUNCTION authz.revoke_api_key(p_id bigint) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE k authz.api_keys;
BEGIN
  PERFORM authz_int.check_writable();
  SELECT * INTO k FROM authz.api_keys WHERE id = p_id AND revoked_at IS NULL;
  IF k.id IS NULL OR NOT (
       EXISTS (SELECT 1 FROM authz.principal() p WHERE p.principal_type = k.principal_type AND p.principal_id = k.user_id)
       OR (k.principal_type = 'user' AND authz_int.may_inspect('user', k.user_id))
       OR (EXISTS (SELECT 1 FROM authz_int.perms WHERE type = k.principal_type AND perm = 'manage_keys')
           AND EXISTS (SELECT 1 FROM authz.principal())
           AND coalesce(authz_int.can(k.principal_type, k.user_id, 'manage_keys'), false))) THEN
    RAISE EXCEPTION 'no API key % of yours', p_id USING HINT = 'rowstile help AZ708';
  END IF;
  UPDATE authz.api_keys SET revoked_at = now() WHERE id = p_id;
  PERFORM authz_int.audit('revoke_api_key', k.principal_type, k.user_id, NULL, NULL, NULL, NULL,
                          jsonb_build_object('key', p_id));
END $f$;

-- Say who is asking, for this transaction: SELECT authz.act_as('user', '42') (NULL, NULL: nobody), first in each
-- transaction. For the app's backend, which signs people in itself; the session is signed, so nothing but this
-- and the logins can change who is signed in. The app role (and its members) may call it.
CREATE OR REPLACE FUNCTION authz.act_as(p_type text, p_id text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  PERFORM authz_int.act_as(p_type, p_id, true);
END $f$;

-- Sign this transaction out: nobody is signed in in it now, and it may sign in again, as anyone. For a test's
-- transaction, which acts for one person, then another, and is rolled back at the end (the SDKs' test modes do
-- it): outside tests a transaction is one principal's, and work for someone else begins a transaction of its own.
CREATE FUNCTION authz.sign_out() RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  PERFORM set_config('authz.user_id', '', true);
  PERFORM set_config('authz.principal_type', '', true);
  PERFORM set_config('authz.scopes', '', true);
  PERFORM set_config('authz.acting_user', '', true);
  PERFORM authz_int.sign();
END $f$;

-- Sign in with an API key for this transaction: SELECT authz.login_key('ak_...'). Returns who:
-- a user's id, or type:id for another principal
CREATE OR REPLACE FUNCTION authz.login_key(p_token text) RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE k authz.api_keys;
BEGIN
  SELECT * INTO k FROM authz.api_keys WHERE hash = encode(sha256(convert_to(coalesce(p_token, ''), 'UTF8')), 'hex');
  IF k.id IS NULL OR k.revoked_at IS NOT NULL OR (k.expires_at IS NOT NULL AND k.expires_at <= now()) THEN
    RAISE EXCEPTION 'invalid API key' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowstile help AZ703';
  END IF;
  PERFORM authz_int.one_principal(CASE WHEN k.principal_type = 'user' THEN '' ELSE k.principal_type END, k.user_id);
  PERFORM set_config('authz.user_id', k.user_id, true);
  PERFORM set_config('authz.principal_type', CASE WHEN k.principal_type = 'user' THEN '' ELSE k.principal_type END, true);
  PERFORM set_config('authz.scopes', k.scopes, true);
  PERFORM set_config('authz.acting_user', '', true);
  PERFORM authz_int.sign();
  IF NOT EXISTS (SELECT 1 FROM authz.principal()) THEN
    RAISE EXCEPTION 'invalid API key' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowstile help AZ703';
  END IF;
  -- when it was last used, to the minute: never waiting on another request with the key (the row they
  -- lock), and not at all in a read-only transaction (a replica, a GET)
  IF pg_catalog.current_setting('transaction_read_only') = 'off' THEN
    UPDATE authz.api_keys SET last_used_at = now()
    WHERE id = (SELECT x.id FROM authz.api_keys x
                WHERE x.id = k.id AND (x.last_used_at IS NULL OR x.last_used_at < now() - interval '1 minute')
                FOR UPDATE SKIP LOCKED);
  END IF;
  PERFORM authz_int.jit_off();
  RETURN authz_int.actor();
END $f$;

-- Sign in with a JWT (HS256) for this transaction: SELECT authz.login_jwt('eyJ...')
-- Settings (authz.settings): jwt_secret (required), jwt_issuer, jwt_audience, jwt_user_claim (default sub),
-- jwt_type_claim (a claim naming the principal's type, for services; absent or 'user': a user).
-- Tokens must carry exp.
-- A 'scope' claim (space separated) limits the transaction to those policy scopes.
CREATE OR REPLACE FUNCTION authz.login_jwt(p_token text) RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE parts text[] := string_to_array(coalesce(p_token, ''), '.'); v_head jsonb; v_claims jsonb; v_secret text;
        v_user text; v_type text; v_scopes text[]; v_now numeric := extract(epoch FROM now()); v_want text;
BEGIN
  SELECT value INTO v_secret FROM authz.settings WHERE key = 'jwt_secret';
  IF v_secret IS NULL THEN RAISE EXCEPTION 'JWT login is not configured (authz.settings jwt_secret)' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowstile help AZ703'; END IF;
  BEGIN
    IF cardinality(parts) <> 3 THEN RAISE EXCEPTION 'bad'; END IF;
    v_head := convert_from(authz_int.b64url(parts[1]), 'UTF8')::jsonb;
    v_claims := convert_from(authz_int.b64url(parts[2]), 'UTF8')::jsonb;
    -- the signatures compared through their hashes: the time it takes says nothing of how much of the token's is right
    IF v_head->>'alg' IS DISTINCT FROM 'HS256'
       OR sha256(authz_int.b64url(parts[3]))
          IS DISTINCT FROM sha256(authz_int.hmac_sha256(convert_to(v_secret, 'UTF8'),
                                                        convert_to(parts[1] || '.' || parts[2], 'UTF8'))) THEN
      RAISE EXCEPTION 'bad';
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'invalid token' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowstile help AZ703';
  END;
  -- an expiry is required; both are numbers of seconds
  IF jsonb_typeof(v_claims->'exp') IS DISTINCT FROM 'number' OR (v_claims->>'exp')::numeric <= v_now
     OR (v_claims ? 'nbf' AND (jsonb_typeof(v_claims->'nbf') <> 'number' OR (v_claims->>'nbf')::numeric > v_now)) THEN
    RAISE EXCEPTION 'token expired or not yet valid' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowstile help AZ703';
  END IF;
  SELECT value INTO v_want FROM authz.settings WHERE key = 'jwt_issuer';
  IF v_want IS NOT NULL AND v_claims->>'iss' IS DISTINCT FROM v_want THEN
    RAISE EXCEPTION 'token from another issuer' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowstile help AZ703';
  END IF;
  SELECT value INTO v_want FROM authz.settings WHERE key = 'jwt_audience';
  -- (coalesce: without the claim both sides are NULL, and a token that names no audience is not for this one)
  IF v_want IS NOT NULL AND NOT coalesce(v_claims->>'aud' = v_want
       OR (jsonb_typeof(v_claims->'aud') = 'array' AND v_claims->'aud' ? v_want), false) THEN
    RAISE EXCEPTION 'token for another audience' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowstile help AZ703';
  END IF;
  v_user := v_claims->>coalesce((SELECT value FROM authz.settings WHERE key = 'jwt_user_claim'), 'sub');
  v_type := v_claims->>(SELECT value FROM authz.settings WHERE key = 'jwt_type_claim');
  IF coalesce(v_type, 'user') <> 'user' AND NOT EXISTS (SELECT 1 FROM authz_int.types WHERE name = v_type AND principal) THEN
    RAISE EXCEPTION 'the token names a type that does not sign in' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowstile help AZ703';
  END IF;
  v_user := coalesce(authz_int.canon(coalesce(v_type, 'user'), v_user), '');
  v_type := CASE WHEN coalesce(v_type, 'user') = 'user' THEN '' ELSE v_type END;
  PERFORM authz_int.one_principal(v_type, v_user);
  PERFORM set_config('authz.user_id', v_user, true);
  PERFORM set_config('authz.principal_type', v_type, true);
  PERFORM set_config('authz.acting_user', '', true);
  IF v_claims ? 'scope' THEN
    v_scopes := ARRAY(SELECT x FROM unnest(string_to_array(v_claims->>'scope', ' ')) x
                      WHERE EXISTS (SELECT 1 FROM authz_int.scope_items WHERE scope = x));
    PERFORM set_config('authz.scopes', CASE WHEN cardinality(v_scopes) = 0 THEN '(none)'
                                            ELSE array_to_string(v_scopes, ',') END, true);
  ELSE
    PERFORM set_config('authz.scopes', '', true);
  END IF;
  PERFORM authz_int.sign();
  IF NOT EXISTS (SELECT 1 FROM authz.principal()) THEN
    RAISE EXCEPTION 'the token names no active user' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowstile help AZ703';
  END IF;
  PERFORM authz_int.jit_off();
  RETURN authz_int.actor();
END $f$;

-- Replace a group's members with the list your identity provider sends (administrators, sync jobs):
-- SELECT * FROM authz.sync_members('team', '10', 'member', ARRAY['1', '2'])
CREATE OR REPLACE FUNCTION authz.sync_members(p_type text, p_id text, p_relation text, p_members text[],
  OUT added int, OUT removed int)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  -- NULL is no list: it would remove every member (a sync job's failed fetch, a missing field)
  IF p_members IS NULL OR EXISTS (SELECT 1 FROM unnest(p_members) x WHERE x IS NULL) THEN
    RAISE EXCEPTION 'say who the members are: a list of ids with no NULL in it (an empty list for none)'
      USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  CASE p_type || '.' || p_relation
    WHEN 'team.member' THEN
      WITH want AS (SELECT DISTINCT x::bigint AS m FROM unnest(p_members) x),
      del AS (DELETE FROM "app"."team_members" s WHERE s."team_id" = p_id::bigint AND s."user_id" NOT IN (SELECT m FROM want) RETURNING 1),
      ins AS (INSERT INTO "app"."team_members" ("team_id", "user_id") SELECT p_id::bigint, w.m FROM want w
              WHERE NOT EXISTS (SELECT 1 FROM "app"."team_members" s WHERE s."team_id" = p_id::bigint AND s."user_id" = w.m) RETURNING 1)
      SELECT (SELECT count(*) FROM ins)::int, (SELECT count(*) FROM del)::int INTO added, removed;
    ELSE RAISE EXCEPTION '%.% has no single table of members to sync (it needs one source: table(group -> user), without where)',
      p_type, p_relation USING HINT = 'rowstile help AZ707';
  END CASE;
  PERFORM authz_int.audit('sync_members', p_type, authz_int.canon(p_type, p_id), p_relation, 'user', NULL, NULL,
                          jsonb_build_object('added', added, 'removed', removed, 'members', p_members));
END $f$;

-- the API keys of user rows that are gone, or whose id changed, are deleted (authz_int.keys_gone)
CREATE OR REPLACE FUNCTION authz_int."user__keys_gone"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  IF TG_OP = 'TRUNCATE' AND NOT EXISTS (SELECT 1 FROM "app"."users") THEN   -- the table is empty, and so are those under it
    PERFORM authz_int.keys_gone('user', NULL);
  ELSIF TG_OP = 'TRUNCATE' THEN   -- TRUNCATE ONLY, or of a table under it: the rows still there keep their keys
    PERFORM authz_int.keys_gone('user', ARRAY(SELECT k.user_id FROM authz.api_keys k WHERE k.principal_type = 'user'
                                              AND NOT EXISTS (SELECT 1 FROM "app"."users" x WHERE x."id"::text = k.user_id)));
  ELSIF TG_OP = 'UPDATE' THEN   -- on a partitioned table (the last trigger below): the ids the update left no row with
    PERFORM authz_int.keys_gone('user', ARRAY(SELECT o."id"::text FROM old_rows o EXCEPT SELECT n."id"::text FROM new_rows n));
  ELSE
    PERFORM authz_int.keys_gone('user', ARRAY(SELECT o."id"::text FROM old_rows o));
  END IF;
  RETURN NULL;
END $f$;

-- before TRUNCATE empties the table, or one under it (each has this trigger: CHILD_TRIGGERS): with a snapshot older
-- than a key made for one of the rows stored there, fail to serialize (the keys go after it, of the rows that are
-- gone: TRUNCATE ONLY, or of a table under it, keeps those of the others)
CREATE OR REPLACE FUNCTION authz_int."user__keys_gone_all"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE v_ids text[];
BEGIN
  IF pg_catalog.current_setting('transaction_isolation') <> 'read committed' THEN
    EXECUTE $q$SELECT ARRAY(SELECT x."id"::text FROM ONLY $q$
            || pg_catalog.quote_ident(TG_TABLE_SCHEMA) || '.' || pg_catalog.quote_ident(TG_TABLE_NAME) || $q$ x)$q$ INTO v_ids;
    PERFORM authz_int.forget_marks('user', v_ids);
  END IF;
  RETURN NULL;
END $f$;

CREATE TRIGGER "authz_user_keys_gone_trunc" AFTER TRUNCATE ON "app"."users"
  FOR EACH STATEMENT EXECUTE FUNCTION authz_int."user__keys_gone"();
COMMENT ON TRIGGER "authz_user_keys_gone_trunc" ON "app"."users" IS 'rowstile: for a TRUNCATE of the tables under its table too';

CREATE TRIGGER "authz_user_keys_gone_trunc_first" BEFORE TRUNCATE ON "app"."users"
  FOR EACH STATEMENT EXECUTE FUNCTION authz_int."user__keys_gone_all"();
COMMENT ON TRIGGER "authz_user_keys_gone_trunc_first" ON "app"."users" IS 'rowstile: for a TRUNCATE of the tables under its table too';

CREATE OR REPLACE FUNCTION authz_int.may_manage(p_type text, p_id text, p_relation text, p_subject text DEFAULT NULL)
RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_perm text := authz_int.manage_perm(p_type, p_relation, p_subject);
BEGIN
  IF authz_int.caller_is_admin() THEN RETURN true; END IF;
  RETURN v_perm IS NOT NULL AND EXISTS (SELECT 1 FROM authz.principal()) AND coalesce(authz_int.can(p_type, p_id, v_perm), false);
END $f$;

-- A pending request goes when its requester's row goes, or its object's (deleted, given a new id, emptied out with
-- its table: p_ids NULL), so that it never reaches whoever later has that id; it is kept, cancelled, with why.
-- Decided requests are history, and stay as they were. (Each lookup is one an index of the pending requests serves,
-- requests_by_object or requests_by_requester: a delete reads none of the decided ones, however many there are)
CREATE OR REPLACE FUNCTION authz_int.requests_gone(p_type text, p_ids text[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF p_ids IS NULL THEN
    UPDATE authz.requests r SET status = 'cancelled', decided_at = now(), note = 'its object is gone'
    WHERE r.status = 'pending' AND r.object_type = p_type;
  ELSE
    UPDATE authz.requests r SET status = 'cancelled', decided_at = now(), note = 'its object is gone'
    WHERE r.status = 'pending' AND r.object_type = p_type AND r.object_id = ANY (p_ids);
  END IF;
  IF p_type <> 'user' THEN
    RETURN;
  ELSIF p_ids IS NULL THEN
    UPDATE authz.requests r SET status = 'cancelled', decided_at = now(), note = 'its requester is gone'
    WHERE r.status = 'pending';
  ELSE
    UPDATE authz.requests r SET status = 'cancelled', decided_at = now(), note = 'its requester is gone'
    WHERE r.status = 'pending' AND r.requester = ANY (p_ids);
  END IF;
END $f$;

-- Emergency access: people who hold 'break_glass' on an object give themselves a relation on it
-- for a short time (one day at most); it is audited and announced on channel authz_alerts
-- (the notification carries the audit row's id; the details stay in authz.audit)
CREATE OR REPLACE FUNCTION authz.break_glass(p_type text, p_id text, p_relation text, p_reason text,
  p_duration interval DEFAULT interval '1 hour') RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE g authz.shares; v_until timestamptz; v_audit bigint; v_held boolean; v_rel authz_int.shared_relations;
BEGIN
  p_id := authz_int.canon(p_type, p_id);
  PERFORM authz_int.check_writable();
  PERFORM authz_int.users_only('authz.break_glass');
  IF coalesce(btrim(p_reason), '') = '' THEN RAISE EXCEPTION 'say why (it is kept in the audit trail)' USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710'; END IF;
  IF p_duration IS NULL OR p_duration <= interval '0' OR p_duration > interval '1 day' THEN
    RAISE EXCEPTION 'emergency access lasts more than nothing and one day at most' USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  -- the object and the user are locked (FOR KEY SHARE), as authz.share locks them: a delete waits for this, or this
  -- for it and then finds nothing to break into
  v_held := authz.uid() IS NOT NULL;
  IF v_held THEN v_held := authz_int.hold(p_type, p_id); END IF;
  IF v_held THEN v_held := authz_int.hold('user', authz.uid()::text); END IF;
  IF NOT v_held
     OR NOT EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_type AND perm = 'break_glass')
     OR NOT authz_int.can(p_type, p_id, 'break_glass') THEN
    RAISE EXCEPTION 'you cannot break the glass on % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  SELECT * INTO v_rel FROM authz_int.shared_relations
  WHERE object_type = p_type AND relation = p_relation AND subject = 'user';
  IF v_rel.relation IS NULL THEN
    RAISE EXCEPTION 'the policy does not allow sharing %.% with a user', p_type, p_relation USING HINT = 'rowstile help AZ706';
  END IF;
  -- the relation's `shared if` holds for whoever breaks the glass, as authz.share asks it of any share
  IF NOT authz_int.share_if(p_type || '.' || p_relation || '.user', p_id, 'user', authz.uid()::text, '') THEN
    RAISE EXCEPTION 'the policy does not allow you %.% on % %, even to break the glass (%)', p_type, p_relation, p_type, p_id,
      coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = v_rel.loc), '?') USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  v_until := now() + p_duration;
  PERFORM set_config('authz_ctx.reason', p_reason, true);
  PERFORM authz_int.mark_row(p_type, p_id);
  PERFORM authz_int.mark_row('user', authz.uid()::text);
  SELECT * INTO g FROM authz.shares WHERE object_type = p_type AND object_id = p_id AND relation = p_relation
    AND subject_type = 'user' AND subject_id = authz.uid()::text AND subject_relation = '' FOR UPDATE;
  IF g.object_id IS NULL THEN
    INSERT INTO authz.shares (object_type, object_id, relation, subject_type, subject_id, subject_relation,
                              expires_at, created_by)
    VALUES (p_type, p_id, p_relation, 'user', authz.uid()::text, '', v_until, authz_int.actor());
  ELSIF (g.expires_at IS NULL OR g.expires_at > now())
        AND (g.caveat IS NOT NULL OR (g.starts_at IS NOT NULL AND g.starts_at > now())) THEN
    -- a share of theirs that starts later or holds while a caveat does: the emergency access would replace it (one
    -- share a subject and relation on an object), and it would be gone when that ends; its manager decides instead
    RAISE EXCEPTION 'a share of yours gives you %.% on % % %, and breaking the glass would replace it', p_type, p_relation,
      p_type, p_id, concat_ws(' ', CASE WHEN g.starts_at > now() THEN 'from ' || g.starts_at END,
                              CASE WHEN g.caveat IS NOT NULL THEN 'while caveat ' || g.caveat || ' holds' END)
      USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ717';
  ELSIF g.expires_at IS NOT NULL AND g.expires_at < v_until THEN
    -- one that ends sooner, or has ended, lasts until then, unconditionally (the old one is in the audit)
    UPDATE authz.shares SET expires_at = v_until, starts_at = NULL, caveat = NULL, caveat_args = NULL
    WHERE object_type = p_type AND object_id = p_id AND relation = p_relation
      AND subject_type = 'user' AND subject_id = authz.uid()::text AND subject_relation = '';
  END IF;
  PERFORM authz_int.audit('break_glass', p_type, p_id, p_relation, 'user', authz.uid()::text, '',
                          jsonb_build_object('until', v_until, 'previous_share', CASE WHEN g.object_id IS NULL THEN NULL
                                             ELSE to_jsonb(g) - 'subject_id' END));
  SELECT max(id) INTO v_audit FROM authz.audit WHERE action = 'break_glass' AND txid = txid_current();
  PERFORM pg_notify('authz_alerts', json_build_object('audit_id', v_audit, 'action', 'break_glass')::text);
END $f$;

CREATE OR REPLACE FUNCTION authz.review_decide(p_review bigint, p_item int, p_keep boolean) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v authz.reviews; i authz.review_items;
BEGIN
  PERFORM authz_int.check_writable();
  PERFORM authz_int.users_only('authz.review_decide');
  SELECT * INTO v FROM authz.reviews WHERE id = p_review AND closed_at IS NULL;
  IF v.id IS NULL OR NOT authz_int.may_inspect(v.object_type, v.object_id) THEN
    RAISE EXCEPTION 'you cannot decide in review %', p_review USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  -- the review's deadline (closes_at, NULL: none): decisions after it are refused; closing applies those made in time
  IF v.closes_at <= now() THEN
    RAISE EXCEPTION 'review % closed for decisions at %', p_review, v.closes_at
      USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ718';
  END IF;
  SELECT * INTO i FROM authz.review_items WHERE review_id = p_review AND item = p_item;
  IF i.item IS NULL THEN RAISE EXCEPTION 'no item % in review %', p_item, p_review USING HINT = 'rowstile help AZ708'; END IF;
  IF NOT authz_int.may_manage(v.object_type, v.object_id, i.relation,
                              authz_int.subject_key(i.subject_type, i.subject_id, i.subject_relation)) THEN
    RAISE EXCEPTION 'you cannot decide on % in review % (you could not unshare it)', i.relation, p_review
      USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  UPDATE authz.review_items SET keep = p_keep, decided_by = authz_int.actor(), decided_at = now()
  WHERE review_id = p_review AND item = p_item;
END $f$;

-- The triggers above that a table under their table lacks, and the statement that makes each
CREATE OR REPLACE FUNCTION authz_int.child_triggers() RETURNS TABLE (child regclass, name name, stmt text)
LANGUAGE sql STABLE SET search_path = pg_catalog, pg_temp AS $f$
  WITH RECURSIVE below(top, oid) AS (
    SELECT i.inhparent, i.inhrelid FROM pg_inherits i
    UNION SELECT b.top, i.inhrelid FROM pg_inherits i JOIN below b ON i.inhparent = b.oid
  )
  SELECT b.oid::regclass, g.tgname,
         overlay(d.def PLACING ' ON ' || c.name || ' ' FROM strpos(d.def, ' ON ' || p.name || ' ')
                 FOR length(' ON ' || p.name || ' '))
  FROM below b
  JOIN pg_class u ON u.oid = b.oid
  JOIN pg_trigger g ON g.tgrelid = b.top AND NOT g.tgisinternal
  JOIN pg_proc f ON f.oid = g.tgfoid AND f.pronamespace = 'authz_int'::regnamespace
   AND CASE WHEN g.tgtype & 1 = 1 THEN NOT u.relispartition         -- a row trigger: Postgres copies it to partitions
            ELSE u.relkind IN ('r', 'p')                            -- a statement trigger: not for TRUNCATE alone,
                 AND (g.tgtype & 28 <> 0 OR f.proname LIKE '%\_\_mirror'  -- but a mirror's,
                      OR EXISTS (SELECT 1 FROM pg_description x WHERE x.objoid = g.oid AND x.classoid = 'pg_trigger'::regclass
                                 AND x.description = 'rowstile: for a TRUNCATE of the tables under its table too')) END  -- and one right there too (below_too)
  CROSS JOIN LATERAL (SELECT pg_get_triggerdef(g.oid) AS def) d
  CROSS JOIN LATERAL (SELECT format('%I.%I', n.nspname, k.relname) AS name
                      FROM pg_class k JOIN pg_namespace n ON n.oid = k.relnamespace WHERE k.oid = b.top) p
  CROSS JOIN LATERAL (SELECT format('%I.%I', n.nspname, k.relname) AS name
                      FROM pg_class k JOIN pg_namespace n ON n.oid = k.relnamespace WHERE k.oid = b.oid) c
  WHERE NOT EXISTS (SELECT 1 FROM pg_description x WHERE x.objoid = g.oid AND x.classoid = 'pg_trigger'::regclass
                    AND x.description = 'rowstile: the trigger of the table above, for the rows stored here')
    AND NOT EXISTS (SELECT 1 FROM pg_trigger h WHERE h.tgrelid = b.oid AND h.tgname = g.tgname)
$f$;

-- Leaks: SELECT * FROM authz.lint()  (administrators; run after schema changes)
CREATE OR REPLACE FUNCTION authz.lint() RETURNS TABLE (severity text, object text, problem text)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE r record; v_role oid := to_regrole('"starter_app"');
BEGIN
  IF v_role IS NULL THEN
    severity := 'error'; object := 'starter_app'; problem := 'the app role does not exist'; RETURN NEXT; RETURN;
  END IF;
  -- the app role itself
  FOR r IN SELECT rolsuper, rolbypassrls FROM pg_roles WHERE oid = v_role AND (rolsuper OR rolbypassrls) LOOP
    severity := 'error'; object := 'starter_app';
    problem := 'is a superuser or has BYPASSRLS: row-level security does not apply to it at all'; RETURN NEXT;
  END LOOP;
  FOR r IN SELECT p.oid::regrole AS parent FROM pg_roles p
           WHERE p.oid <> v_role AND (p.rolsuper OR p.rolbypassrls) AND pg_has_role(v_role, p.oid, 'MEMBER') LOOP
    severity := 'error'; object := 'starter_app';
    problem := format('is a member of %s, which bypasses row-level security', r.parent); RETURN NEXT;
  END LOOP;
  -- the policy's owner (or a member of it): its sessions are believed unsigned, it may read rowstile's tables
  -- (the session key among them) and turn row-level security off (applying refuses it, AZ624: this finds a grant made since)
  FOR r IN SELECT n.nspowner::regrole AS owner FROM pg_namespace n, pg_roles a
           WHERE n.nspname = 'authz_int' AND a.oid = v_role AND NOT a.rolsuper AND pg_has_role(v_role, n.nspowner, 'MEMBER') LOOP
    severity := 'error'; object := 'starter_app';
    problem := format('is the policy''s owner %s, or a member of it: who is signed in is believed without a signature, and it may read rowstile''s tables and turn row-level security off. The app role must be a role of its own: not the tables'' owner or the policy''s, nor a member of either', r.owner);
    RETURN NEXT;
  END LOOP;
  -- rowstile's own objects: nobody but the owner uses them, except for what the policy grants
  FOR r IN SELECT n.nspname::text AS object, gw.who, a.privilege_type AS privilege,
       format('REVOKE %s ON SCHEMA %I FROM %s CASCADE', a.privilege_type, n.nspname, gw.who) AS stmt
  FROM pg_namespace n, aclexplode(n.nspacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int') AND a.grantee <> n.nspowner
    AND NOT (a.grantee = '"starter_app"'::regrole AND n.nspname <> 'authz_int' AND a.privilege_type = 'USAGE')
UNION ALL
SELECT c.oid::regclass::text, gw.who, a.privilege_type,
       format('REVOKE %s ON %s %s FROM %s CASCADE', a.privilege_type, CASE c.relkind WHEN 'S' THEN 'SEQUENCE' ELSE 'TABLE' END,
              c.oid::regclass, gw.who)
  FROM pg_class c, aclexplode(c.relacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> c.relowner
    AND NOT (a.grantee = '"starter_app"'::regrole AND a.privilege_type = 'SELECT'
             AND c.relnamespace::regnamespace::text || '."' || replace(c.relname, '"', '""') || '"' = ANY (ARRAY['authz_gen."policy_lines"', 'authz_int."document__editor"', 'authz_int."document__viewer"']::text[]))
UNION ALL
SELECT format('%s (%I)', c.oid::regclass, att.attname), gw.who, a.privilege_type,
       format('REVOKE %s (%I) ON %s FROM %s CASCADE', a.privilege_type, att.attname, c.oid::regclass, gw.who)
  FROM pg_class c JOIN pg_attribute att ON att.attrelid = c.oid, aclexplode(att.attacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND att.attacl IS NOT NULL
UNION ALL
SELECT p.oid::regprocedure::text, gw.who, a.privilege_type,
       format('REVOKE %s ON ROUTINE %s FROM %s CASCADE', a.privilege_type, p.oid::regprocedure, gw.who)
  FROM pg_proc p, aclexplode(p.proacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE p.pronamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> p.proowner
    AND NOT (p.pronamespace = 'authz_int'::regnamespace AND a.grantee IN (0, '"starter_app"'::regrole))
    AND NOT (p.pronamespace = 'authz_gen'::regnamespace AND a.grantee = '"starter_app"'::regrole
             AND '"' || replace(p.proname, '"', '""') || '"' = ANY (ARRAY['"app.documents:column owner_id:items"', '"app.documents:column owner_id:why"', '"app.documents:delete:items"', '"app.documents:delete:why"', '"app.documents:insert:items"', '"app.documents:insert:refuse"', '"app.documents:insert:why"', '"app.documents:rules:explain"', '"app.documents:update:items"', '"app.documents:update:refuse"', '"app.documents:update:why"']::text[]))
    AND NOT (p.pronamespace = 'authz'::regnamespace AND a.grantee = '"starter_app"'::regrole AND p.oid = ANY (ARRAY['authz.uid()', 'authz.principal()', 'authz.ctx(text)', 'authz.link_hashes()', 'authz.act_as(text, text)', 'authz.sign_out()', 'authz.connection_check()', 'authz.session_limited()', 'authz.can(text, text, text)', 'authz.list(text, text, text, integer)', 'authz.perms(text, text)', 'authz.perms_of(text, text[])', 'authz.share(text, text, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, text, text, text, text, text)', 'authz.create_link(text, text, text, timestamptz)', 'authz.list_links(text, text)', 'authz.revoke_link(text, text, text)', 'authz.create_role(text, text, text, text, text[])', 'authz.set_role_permissions(bigint, text[])', 'authz.delete_role(bigint)', 'authz.roles_of(text, text)', 'authz.who(text, text, text)', 'authz.explain(text, text, text, text)', 'authz.list_shares(text, text)', 'authz.explain_rule(text, text, text, jsonb)', 'authz.who_among(text, text, text, text[], text)', 'authz.create_api_key(text, text, timestamptz, text, text)', 'authz.list_api_keys(text, text)', 'authz.revoke_api_key(bigint)', 'authz.login_key(text)', 'authz.login_jwt(text)', 'authz.view_as(text, text)', 'authz.request_access(text, text, text, text, interval)', 'authz.pending_requests()', 'authz.decide_request(bigint, boolean, text)', 'authz.cancel_request(bigint)', 'authz.break_glass(text, text, text, text, interval)', 'authz.start_review(text, text, timestamptz)', 'authz.review_items(bigint)', 'authz.review_decide(bigint, integer, boolean)', 'authz.close_review(bigint, boolean)', 'authz.who(text, bigint, text)', 'authz.explain(text, bigint, text, text)', 'authz.list_shares(text, bigint)', 'authz.list_links(text, bigint)', 'authz.revoke_link(text, bigint, text)', 'authz.create_link(text, bigint, text, timestamptz)', 'authz.create_role(text, bigint, text, text, text[])', 'authz.roles_of(text, bigint)', 'authz.request_access(text, bigint, text, text, interval)', 'authz.break_glass(text, bigint, text, text, interval)', 'authz.start_review(text, bigint, timestamptz)', 'authz.can(text, bigint, text)', 'authz.who_among(text, bigint, text, text[], text)', 'authz.perms(text, bigint)', 'authz.share(text, text, text, text, bigint, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, text, text, text, bigint, text)', 'authz.share(text, bigint, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, bigint, text, text, text, text)', 'authz.share(text, bigint, text, text, bigint, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, bigint, text, text, bigint, text)']::regprocedure[])) LOOP
    severity := 'error'; object := r.object;
    problem := format('%s holds %s on it, which the policy doesn''t give (a default privilege of the owner, or a grant made since the last apply): the next apply takes it back, or %s', r.who, r.privilege, r.stmt);
    RETURN NEXT;
  END LOOP;
  -- schemas on the search path of the functions that run as the owner, which others may create in
  FOR r IN SELECT n.nspname::text AS schema, w.who
FROM pg_catalog.unnest(authz_int.policy_path()) s(name) JOIN pg_catalog.pg_namespace n ON n.nspname = s.name,
LATERAL (SELECT CASE WHEN EXISTS (SELECT 1 FROM pg_catalog.aclexplode(n.nspacl) a
                                  WHERE a.grantee = 0 AND a.privilege_type = 'CREATE') THEN 'PUBLIC'
                ELSE (SELECT pg_catalog.string_agg(ro.rolname::text, ', ' ORDER BY ro.rolname) FROM pg_catalog.pg_roles ro
                      WHERE pg_catalog.has_schema_privilege(ro.oid, n.oid, 'CREATE') AND NOT ro.rolsuper
                        AND ro.rolname <> 'pg_database_owner' AND NOT pg_catalog.pg_has_role(ro.oid, (SELECT nspowner FROM pg_namespace WHERE nspname = 'authz_int'), 'MEMBER')
                        AND NOT pg_catalog.pg_has_role(ro.oid, (SELECT d.datdba FROM pg_catalog.pg_database d
                                                               WHERE d.datname = pg_catalog.current_database()), 'MEMBER'))
                END AS who) w
-- a temporary schema is the session's own, and never searched for functions or operators
WHERE w.who IS NOT NULL AND n.nspname !~ '^pg_(toast_)?temp_' LOOP
    severity := 'error'; object := r.schema;
    problem := format('is on the search path of rowstile''s functions that run as the owner, and %s may create in it: a function there can take the place of a built-in one and run as the owner. REVOKE CREATE ON SCHEMA %I FROM %s, or apply with a search path without it', r.who, r.schema, r.who);
    RETURN NEXT;
  END LOOP;
  -- the audit trail's guard, which fires in every replication role (ENABLE ALWAYS): ENABLE TRIGGER ALL, which a
  -- data-only pg_restore --disable-triggers ends with, puts it back for ordinary sessions only
  FOR r IN SELECT t.name, g.tgenabled::text AS mode
           FROM (VALUES ('authz_audit_append_only'), ('authz_audit_no_truncate')) t (name)
           LEFT JOIN pg_trigger g ON g.tgrelid = 'authz.audit'::regclass AND g.tgname = t.name
           WHERE g.tgenabled IS DISTINCT FROM 'A' LOOP
    severity := 'warning'; object := 'authz.audit';
    problem := format('the trigger %s %s. rowstile reapply puts it back, in every replication role', r.name,
      CASE r.mode
        WHEN 'O' THEN 'guards it in ordinary sessions only: one with session_replication_role = replica may change the trail (ENABLE TRIGGER ALL leaves it so, as at the end of a data-only pg_restore --disable-triggers)'
        WHEN 'R' THEN 'guards it with session_replication_role = replica only: an ordinary session may change the trail'
        WHEN 'D' THEN 'that guards it is off: the trail may be changed'
        ELSE 'that guards it is missing: the trail may be changed' END);
    RETURN NEXT;
  END LOOP;
  -- governed tables
  FOR r IN SELECT c.oid::regclass AS tbl, c.relrowsecurity, c.relowner,
                  c.oid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."documents"']::text[]) x) AS governed
           FROM pg_class c WHERE c.oid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."documents"', '"app"."teams"', '"app"."users"']::text[]) x) LOOP
    -- (FORCE ROW LEVEL SECURITY is no way out: an owner may turn it off again, and row-level security with it)
    IF pg_has_role(v_role, r.relowner, 'MEMBER') THEN
      severity := 'error'; object := r.tbl::text;
      problem := format('is owned by %s (or a role it belongs to): an owner skips row-level security, and may turn it off, FORCE ROW LEVEL SECURITY or not. The app role must not own the tables: ALTER TABLE %s OWNER TO the role that applies the policy', 'starter_app', r.tbl);
      RETURN NEXT;
    END IF;
    IF NOT r.relrowsecurity AND r.governed THEN
      severity := 'error'; object := r.tbl::text;
      problem := format('row-level security is off, so the policy''s rules don''t apply to it: %s reads and writes every row it has privileges on. Apply the policy again (it turns it on), or ALTER TABLE %s ENABLE ROW LEVEL SECURITY', 'starter_app', r.tbl);
      RETURN NEXT;
    ELSIF NOT r.relrowsecurity AND has_any_column_privilege(v_role, r.tbl, 'SELECT') THEN
      severity := 'info'; object := r.tbl::text;
      problem := format('%s may read every row (the policy has no rules for this table): fine for a directory, otherwise add rules', 'starter_app');
      RETURN NEXT;
    END IF;
    IF has_table_privilege(v_role, r.tbl, 'TRUNCATE') THEN
      severity := 'error'; object := r.tbl::text;
      problem := format('%s may TRUNCATE it, which skips row-level security: REVOKE TRUNCATE ON %s FROM %s', 'starter_app', r.tbl, 'starter_app');
      RETURN NEXT;
    END IF;
  END LOOP;
  -- policies on governed tables that rowstile didn't make (left from before, or made by a migration) and that
  -- apply to the app role: Postgres joins permissive policies with OR, so one widens what the rules allow
  FOR r IN SELECT p.polname, p.polrelid::regclass AS tbl, p.polpermissive,
                  CASE p.polcmd WHEN 'r' THEN 'select' WHEN 'a' THEN 'insert' WHEN 'w' THEN 'update'
                                WHEN 'd' THEN 'delete' ELSE 'every command' END AS cmd
           FROM pg_policy p
           LEFT JOIN pg_description d ON d.objoid = p.oid AND d.classoid = 'pg_policy'::regclass
           WHERE p.polrelid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."documents"']::text[]) x)
             AND coalesce(d.description, '') NOT IN ('rowstile')
             AND EXISTS (SELECT 1 FROM unnest(p.polroles) o
                         WHERE CASE WHEN o = 0 THEN true ELSE pg_has_role(v_role, o, 'MEMBER') END)
           ORDER BY p.polrelid::regclass::text, p.polname LOOP
    object := r.tbl::text;
    IF r.polpermissive THEN
      severity := 'error';
      problem := format('the policy %I (%s) on it is not rowstile''s: Postgres joins a table''s policies with OR, so it lets %s through whatever the rules say. DROP POLICY %I ON %s, and say what it allowed in the policy file', r.polname, r.cmd, 'starter_app', r.polname, r.tbl);
    ELSE
      severity := 'info';
      problem := format('the restrictive policy %I (%s) on it is not rowstile''s: %s gets less than the rules give, and a write it refuses fails with Postgres''s own message, not a reason', r.polname, r.cmd, 'starter_app');
    END IF;
    RETURN NEXT;
  END LOOP;
  -- tables beside the policy's (in their schemas) that it doesn't name: nothing filters what the app role reads there
  FOR r IN SELECT c.oid::regclass AS tbl FROM pg_class c
           WHERE c.relkind IN ('r', 'p') AND NOT c.relispartition AND NOT c.relrowsecurity
             AND c.relnamespace IN (SELECT k.relnamespace FROM unnest(ARRAY['"app"."documents"', '"app"."teams"', '"app"."users"', '"app"."team_members"']::text[]) x
                                    JOIN pg_class k ON k.oid = to_regclass(x))
             AND c.oid NOT IN (SELECT to_regclass(x)::oid FROM unnest(ARRAY['"app"."documents"', '"app"."teams"', '"app"."users"', '"app"."team_members"']::text[]) x
                               WHERE to_regclass(x) IS NOT NULL)
             AND has_any_column_privilege(v_role, c.oid, 'SELECT')
           ORDER BY c.oid::regclass::text LOOP
    severity := 'info'; object := r.tbl::text;
    problem := format('%s may read every row, and the policy doesn''t name this table: fine for a lookup table, otherwise give it a type and rules', 'starter_app');
    RETURN NEXT;
  END LOOP;
  -- partitions and inheritance children: used directly, they skip the rules of the table above (apply turns
  -- row-level security on for the ones there are then; later ones are found here), and TRUNCATE skips the
  -- triggers for TRUNCATE alone that are not right there (the sync mirror's). The tables above: those
  -- with rules, and those rowstile watches (a trigger of its own on them)
  FOR r IN WITH RECURSIVE x(tbl, governed) AS (
             SELECT to_regclass(t), true FROM unnest(ARRAY['"app"."documents"']::text[]) t
             UNION SELECT DISTINCT g.tgrelid::regclass, false FROM pg_trigger g
             JOIN pg_proc f ON f.oid = g.tgfoid AND f.pronamespace = 'authz_int'::regnamespace
             WHERE NOT g.tgisinternal AND g.tgrelid NOT IN (SELECT to_regclass(t) FROM unnest(ARRAY['"app"."documents"']::text[]) t
                                                           WHERE to_regclass(t) IS NOT NULL)
               AND NOT EXISTS (SELECT 1 FROM pg_description c WHERE c.objoid = g.oid AND c.classoid = 'pg_trigger'::regclass
                               AND c.description = 'rowstile: the trigger of the table above, for the rows stored here')),
           d(oid, top, governed) AS (
             SELECT i.inhrelid, i.inhparent, x.governed FROM pg_inherits i JOIN x ON i.inhparent = x.tbl
             UNION SELECT i.inhrelid, d.top, d.governed FROM pg_inherits i JOIN d ON i.inhparent = d.oid)
           SELECT d.oid::regclass AS part, d.top::regclass AS tbl, d.governed, k.relrowsecurity
           FROM d JOIN pg_class k ON k.oid = d.oid LOOP
    IF has_table_privilege(v_role, r.part, 'TRUNCATE') THEN
      severity := 'error'; object := r.part::text;
      problem := format('is a partition of %s (or inherits from it), and %s may TRUNCATE it, which skips row-level security: REVOKE TRUNCATE ON %s FROM %s', r.tbl, 'starter_app', r.part, 'starter_app');
      RETURN NEXT;
    END IF;
    -- (on a table without rules, statements on it run the triggers of the table above as their own: the next loop
    -- finds one made since that lacks them)
    -- (one column's privilege is enough: no DELETE has columns)
    IF r.governed AND NOT r.relrowsecurity AND (has_any_column_privilege(v_role, r.part, 'INSERT') OR has_any_column_privilege(v_role, r.part, 'UPDATE')
                                 OR has_table_privilege(v_role, r.part, 'DELETE') OR has_any_column_privilege(v_role, r.part, 'SELECT')) THEN
      severity := 'error'; object := r.part::text;
      problem := format('is a partition of %s (or inherits from it), and %s may use it directly, without %s''s rules or the triggers that keep inheritance and the audit current: apply the policy again (it turns row-level security on for it), or ALTER TABLE %s ENABLE ROW LEVEL SECURITY', r.tbl, 'starter_app', r.tbl, r.part);
      RETURN NEXT;
    END IF;
  END LOOP;
  -- partitions and tables that inherit, made since the last apply: Postgres runs a table's row triggers for its
  -- own rows and its partitions' only, and its statement triggers for statements on it only; applying gives
  -- them to each table under it (whatever the app role may do there: the owner's statements count too, and
  -- rows written through the table above need no privilege of their own)
  FOR r IN SELECT c.child, k.relispartition AS part, (SELECT i.inhparent::regclass FROM pg_inherits i WHERE i.inhrelid = c.child LIMIT 1) AS above,
                  string_agg(c.name::text, ', ' ORDER BY c.name) AS names
           FROM authz_int.child_triggers() c JOIN pg_class k ON k.oid = c.child GROUP BY c.child, k.relispartition LOOP
    severity := 'error'; object := r.child::text;
    IF r.part THEN
      problem := format('is a partition of %s, and was made since the policy was last applied: Postgres runs a table''s statement triggers for statements on it only, so a statement on this partition doesn''t keep inheritance, shares and the audit current (missing here: %s). Apply the policy again (it makes them)', r.above, r.names);
    ELSE
      problem := format('inherits from %s, and was made since the policy was last applied: Postgres runs a table''s row triggers for its own rows only, and its statement triggers for statements on it only, so a rule on a column is not checked on the rows stored here, their shares stay when their key changes, and a statement on this table doesn''t keep inheritance, shares and the audit current (missing here: %s). Apply the policy again (it makes them)', r.above, r.names);
    END IF;
    RETURN NEXT;
  END LOOP;
  -- unique constraints on governed tables tell people that rows they cannot see exist
  FOR r IN SELECT i.indexrelid::regclass AS idx, i.indrelid::regclass AS tbl
           FROM pg_index i WHERE i.indisunique AND NOT i.indisprimary
             AND i.indrelid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."documents"']::text[]) x)
             AND has_any_column_privilege(v_role, i.indrelid, 'INSERT') LOOP
    severity := 'info'; object := r.idx::text;
    problem := format('a unique index on %s: inserting a duplicate fails even when the existing row is hidden, which tells the user it exists', r.tbl);
    RETURN NEXT;
  END LOOP;
  -- primary keys the app role may choose (a key column it may insert or update, not GENERATED ALWAYS; not one the
  -- index only INCLUDEs, which it holds but is not keyed by): the same
  FOR r IN SELECT i.indexrelid::regclass AS idx, i.indrelid::regclass AS tbl
           FROM pg_index i WHERE i.indisprimary
             AND i.indrelid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."documents"']::text[]) x)
             AND EXISTS (SELECT 1 FROM pg_attribute a
                         WHERE a.attrelid = i.indrelid AND a.attnum = ANY ((i.indkey::int2[])[0:i.indnkeyatts - 1]) AND a.attidentity <> 'a'
                           AND (has_column_privilege(v_role, i.indrelid, a.attnum, 'INSERT')
                                OR has_column_privilege(v_role, i.indrelid, a.attnum, 'UPDATE'))) LOOP
    severity := 'info'; object := r.idx::text;
    problem := format('the primary key of %s, which %s may choose: an insert with the id of a hidden row fails, which tells the user it exists. Let the database make the ids (GENERATED ALWAYS AS IDENTITY, or random uuids), or revoke INSERT and UPDATE on the key', r.tbl, 'starter_app');
    RETURN NEXT;
  END LOOP;
  -- masked columns must only be readable through their view
  FOR r IN SELECT m.tbl, m.col, m.view FROM authz_int.masked_columns m
           WHERE CASE WHEN EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = to_regclass(m.tbl) AND a.attname = m.col
                                   AND a.attnum > 0 AND NOT a.attisdropped)
                      THEN has_column_privilege(v_role, m.tbl, m.col, 'SELECT') ELSE false END LOOP
    severity := 'error'; object := to_regclass(r.tbl)::text || '.' || r.col;
    problem := format('the policy masks it, but %s may read it from the table (a GRANT to the role, a role it belongs to, or PUBLIC): read it through %s and revoke that', 'starter_app', r.view);
    RETURN NEXT;
  END LOOP;
  -- tables holding relationships (memberships, links) the app role may change directly
  FOR r IN SELECT to_regclass(v.tbl) AS tbl, v.readers, v.typed
           FROM (VALUES ('"app"."team_members"', 'team.member', false)) v(tbl, readers, typed) LOOP
    CONTINUE WHEN r.tbl IS NULL;
    IF has_table_privilege(v_role, r.tbl, 'TRUNCATE') THEN
      severity := 'error'; object := r.tbl::text;
      problem := format('%s may TRUNCATE it, which empties memberships without row-level security: REVOKE TRUNCATE ON %s FROM %s', 'starter_app', r.tbl, 'starter_app');
      RETURN NEXT;
    END IF;
    IF (has_any_column_privilege(v_role, r.tbl, 'INSERT') OR has_any_column_privilege(v_role, r.tbl, 'UPDATE')
        OR has_table_privilege(v_role, r.tbl, 'DELETE'))
       AND NOT (SELECT relrowsecurity FROM pg_class WHERE oid = r.tbl) THEN
      severity := 'error'; object := r.tbl::text;
      problem := format('%s may change it, and it decides who is in what: anyone could add themselves. Revoke the write privileges, or give it rules', 'starter_app');
      RETURN NEXT;
    END IF;
    -- ... or read in full: who is linked to what (a type's table without rules is named above)
    IF NOT r.typed AND NOT (SELECT relrowsecurity FROM pg_class WHERE oid = r.tbl)
       AND has_any_column_privilege(v_role, r.tbl, 'SELECT') THEN
      severity := 'info'; object := r.tbl::text;
      problem := format('%s may read every row, and the policy reads it for %s: who is linked to what is readable. Fine where that is no secret, otherwise give it a type and rules', 'starter_app', r.readers);
      RETURN NEXT;
    END IF;
  END LOOP;
  -- columns that grant a relation, changed by anyone who may update the row
  FOR r IN SELECT * FROM (VALUES (NULL::text, NULL::text, NULL::text, NULL::text, NULL::text)) v(tbl, col, what, loc, ask)
           WHERE tbl IS NOT NULL LOOP
    IF EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = to_regclass(r.tbl) AND a.attname = r.col
               AND a.attnum > 0 AND NOT a.attisdropped)
       AND has_column_privilege(v_role, r.tbl, r.col, 'UPDATE') THEN
      severity := 'warning'; object := to_regclass(r.tbl)::text || '.' || r.col;
      problem := format('grants %s (%s), and anyone who may update the row may change it: add a rule such as "update %s : %s"', r.what, coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = r.loc), '?'), r.col, r.ask);
      RETURN NEXT;
    END IF;
  END LOOP;
  -- rules for a command the app role has no privilege for (one column's is enough for a read, an insert or
  -- an update: the app may write some columns only)
  FOR r IN SELECT to_regclass(v.tbl) AS tbl, v.cmd FROM (VALUES ('"app"."documents"', 'delete'), ('"app"."documents"', 'insert'), ('"app"."documents"', 'select'), ('"app"."documents"', 'update')) v(tbl, cmd)
           WHERE v.tbl IS NOT NULL LOOP
    CONTINUE WHEN r.tbl IS NULL;
    IF r.cmd = 'delete' THEN
      CONTINUE WHEN has_table_privilege(v_role, r.tbl, 'DELETE');
    ELSE
      CONTINUE WHEN has_any_column_privilege(v_role, r.tbl, r.cmd);
    END IF;
    severity := 'warning'; object := r.tbl::text;
    problem := format('the policy has a rule for %s, but %s has no %s privilege on the table: the rule never applies, and the statement fails with Postgres''s own "permission denied for table". GRANT %s ON %s TO %s, or make the rule "%s : nobody"', r.cmd, 'starter_app', upper(r.cmd), upper(r.cmd), r.tbl, 'starter_app', r.cmd);
    RETURN NEXT;
  END LOOP;
  -- relations named like a type that signs in
  FOR r IN SELECT * FROM (VALUES (NULL::text, NULL::text, NULL::text)) v(type, rel, loc)
           WHERE type IS NOT NULL LOOP
    severity := 'info'; object := r.type || '.' || r.rel;
    problem := format('is named like the type %s (%s), which signs in: alone in a rule it reads like any %s, and it is this row''s. A name that says what the relation is (author, owner) reads better', r.rel, coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = r.loc), '?'), r.rel);
    RETURN NEXT;
  END LOOP;
  -- columns that move a row under another, with nothing checking where it moves to
  FOR r IN SELECT * FROM (VALUES (NULL::text, NULL::text, NULL::text, NULL::text)) v(tbl, col, rel, loc)
           WHERE tbl IS NOT NULL LOOP
    -- (a composite key's columns are 'org_id, parent_id': any of them it may update)
    IF EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = to_regclass(r.tbl) AND a.attnum > 0 AND NOT a.attisdropped
               AND a.attname::text = ANY (string_to_array(r.col, ', ')) AND has_column_privilege(v_role, r.tbl, a.attnum, 'UPDATE')) THEN
      severity := 'warning'; object := to_regclass(r.tbl)::text || '.' || r.col;
      problem := format('moves a row under another (%s, %s), and nothing checks where it moves to, so anyone who may update a row may put it inside something they may not change: add a rule such as "update %s after : %s.edit"', r.rel, coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = r.loc), '?'), r.col, r.rel);
      RETURN NEXT;
    END IF;
  END LOOP;
  -- views over governed tables that run with their owner's rights
  FOR r IN SELECT DISTINCT v.oid::regclass AS view, d.refobjid::regclass AS tbl
           FROM pg_depend d JOIN pg_rewrite w ON w.oid = d.objid JOIN pg_class v ON v.oid = w.ev_class
           LEFT JOIN pg_description ds ON ds.objoid = v.oid AND ds.classoid = 'pg_class'::regclass
           WHERE d.classid = 'pg_rewrite'::regclass AND d.refclassid = 'pg_class'::regclass
             AND d.refobjid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."documents"', '"app"."teams"', '"app"."users"', '"app"."team_members"']::text[]) x)
             AND v.oid <> d.refobjid AND v.relkind IN ('v', 'm')
             AND v.relnamespace NOT IN (to_regnamespace('authz_gen'), to_regnamespace('authz_int'))
             AND coalesce(ds.description, '') NOT IN ('rowstile masked view')
             AND NOT coalesce(v.reloptions @> ARRAY['security_invoker=true'], false)
             AND NOT coalesce(v.reloptions @> ARRAY['security_invoker=on'], false)
             AND has_any_column_privilege(v_role, v.oid, 'SELECT') LOOP
    severity := 'error'; object := r.view::text;
    problem := format('%s may read this view of %s, and views run with their owner''s rights, so row-level security does not apply: ALTER VIEW %s SET (security_invoker = on)', 'starter_app', r.tbl, r.view);
    RETURN NEXT;
  END LOOP;
  -- functions that read governed tables as their owner
  FOR r IN SELECT p.oid::regprocedure AS fn FROM pg_proc p
           WHERE p.prosecdef AND p.pronamespace NOT IN (to_regnamespace('authz'), to_regnamespace('authz_int'),
                                                       to_regnamespace('authz_gen'), 'pg_catalog'::regnamespace)
             AND has_function_privilege(v_role, p.oid, 'EXECUTE')
             AND p.prokind IN ('f', 'p')
             AND EXISTS (SELECT 1 FROM unnest(ARRAY['app.documents', 'app.teams', 'app.users', 'app.team_members']::text[]) x
                         WHERE lower(replace(pg_get_functiondef(p.oid), '"', '')) ~
                               ('(from|join|update|into|table|only)\s+(' || lower(split_part(x, '.', 1)) || '\.)?'
                                || lower(split_part(x, '.', 2)) || '([^a-z0-9_$]|$)')) LOOP
    severity := 'warning'; object := r.fn::text;
    problem := 'SECURITY DEFINER, callable by the app role, and seems to use a governed table: it reads rows without row-level security unless its owner is subject to it';
    RETURN NEXT;
  END LOOP;
  -- lookups the permission views make
  FOR r IN SELECT * FROM (VALUES ('"app"."users"', 'id', 'user: find one by its key, for checks and write rules', NULL), ('"app"."team_members"', 'team_id', 'team.member: find the members of an object', NULL), ('"app"."team_members"', 'user_id', 'team.member: find what a subject is in', NULL), ('"app"."teams"', 'id', 'team: find one by its key, for checks and write rules', NULL), ('"app"."documents"', 'owner_id', 'document.owner: find objects by owner_id', NULL), ('"app"."documents"', 'id', 'document: find one by its key, for checks and write rules', NULL)) v(tbl, col, why, alone) WHERE tbl IS NOT NULL LOOP
    CONTINUE WHEN to_regclass(r.tbl) IS NULL;
    -- a plain view can't have an index: the tables under it answer the lookups
    CONTINUE WHEN (SELECT c.relkind FROM pg_class c WHERE c.oid = to_regclass(r.tbl)) = 'v';
    -- an index whose first columns are these (one, or a composite key's, in any order), or what serves a (type, id)
    -- pair alone (its ids where they are two columns, its type where its id is one): a finished one, with no
    -- condition (the lookups are joins, which a partial index doesn't serve), as rowstile indexes counts them; its key
    -- columns only (an index on (a) INCLUDE (b) is not sorted by b)
    IF NOT EXISTS (SELECT 1 FROM pg_index i, unnest(ARRAY[r.col, r.alone]) w(cs)
                   WHERE w.cs IS NOT NULL AND i.indrelid = to_regclass(r.tbl) AND i.indisvalid AND i.indpred IS NULL
                     AND (SELECT array_agg(a.attname::text ORDER BY a.attname)
                          FROM unnest((i.indkey::int2[])[0:least(cardinality(string_to_array(w.cs, ', ')), i.indnkeyatts) - 1]) k
                          JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = k)
                         = (SELECT array_agg(c ORDER BY c) FROM unnest(string_to_array(w.cs, ', ')) c)) THEN
      severity := 'performance'; object := to_regclass(r.tbl)::text || '.' || r.col;
      problem := format('no index starts with %s (%s): CREATE INDEX ON %s (%s)',
                        CASE WHEN r.col LIKE '%, %' THEN 'these columns' ELSE 'this column' END, r.why, to_regclass(r.tbl),
                        (SELECT string_agg(quote_ident(c), ', ') FROM unnest(string_to_array(r.col, ', ')) c));
      RETURN NEXT;
    END IF;
  END LOOP;
END $f$;

-- What is wrong with this connection, for the app to check when it starts: SELECT * FROM authz.connection_check()
-- 'error': the rules don't apply to the role this connection runs as. No rows: all is well.
CREATE OR REPLACE FUNCTION authz.connection_check() RETURNS TABLE (severity text, problem text)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_me oid := (SELECT oid FROM pg_roles WHERE rolname = authz_int.caller_role()); v_app oid := to_regrole('"starter_app"'); r record;
BEGIN
  IF (SELECT rolsuper FROM pg_roles WHERE oid = v_me) THEN
    severity := 'error'; problem := format('%s is a superuser: row-level security does not apply to it', v_me::regrole);
    RETURN NEXT; RETURN;
  END IF;
  IF (SELECT rolbypassrls FROM pg_roles WHERE oid = v_me) THEN
    severity := 'error'; problem := format('%s has BYPASSRLS: row-level security does not apply to it', v_me::regrole);
    RETURN NEXT;
  END IF;
  -- the policy's owner (or a member of it): who is signed in is believed without a signature
  IF pg_has_role(v_me, (SELECT nspowner FROM pg_namespace WHERE nspname = 'authz_int'), 'MEMBER') THEN
    severity := 'error';
    problem := format('%s is the policy''s owner, or a member of it: who is signed in is believed without a signature, and it may turn row-level security off. Log in as an app role of its own', v_me::regrole);
    RETURN NEXT;
  END IF;
  -- a table's owner skips row-level security, and may turn it off: FORCE or not. A member of it, its rights
  -- inherited or not (it may SET ROLE), as well
  FOR r IN SELECT c.oid::regclass AS tbl FROM pg_class c
           WHERE c.oid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."documents"']::text[]) x)
             AND pg_has_role(v_me, c.relowner, 'MEMBER') LOOP
    severity := 'error';
    problem := format('%s owns %s, or is a member of its owner: an owner skips row-level security, and may turn it off', v_me::regrole, r.tbl);
    RETURN NEXT;
  END LOOP;
  -- a table with rules whose row-level security is off: the rules don't apply
  FOR r IN SELECT c.oid::regclass AS tbl FROM pg_class c
           WHERE c.oid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."documents"']::text[]) x) AND NOT c.relrowsecurity LOOP
    severity := 'error';
    problem := format('row-level security is off on %s: the policy''s rules don''t apply to it', r.tbl);
    RETURN NEXT;
  END LOOP;
  -- a login that switched to the app role (SET ROLE) but is an administrator: RESET ROLE leaves row-level
  -- security, and its sessions are believed without a signature
  FOR r IN SELECT l.oid::regrole AS login FROM pg_roles l, pg_namespace n
           WHERE l.rolname = session_user AND n.nspname = 'authz_int' AND l.oid <> v_me
             AND (l.rolsuper OR l.rolbypassrls OR pg_has_role(l.oid, n.nspowner, 'MEMBER')) LOOP
    severity := 'error';
    problem := format('this connection logs in as %s, a superuser, BYPASSRLS or the policy''s owner, and switched to %s: RESET ROLE leaves row-level security, and who is signed in is believed without a signature. Log in as the app role', r.login, v_me::regrole);
    RETURN NEXT;
  END LOOP;
  -- ... or a member of a table's owner (another role than the policy's, said above): RESET ROLE, then SET ROLE to
  -- the owner, leaves row-level security
  FOR r IN SELECT l.oid::regrole AS login, c.oid::regclass AS tbl FROM pg_roles l, pg_namespace n, pg_class c
           WHERE l.rolname = session_user AND n.nspname = 'authz_int' AND l.oid <> v_me
             AND NOT (l.rolsuper OR l.rolbypassrls OR pg_has_role(l.oid, n.nspowner, 'MEMBER'))
             AND c.oid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."documents"']::text[]) x)
             AND pg_has_role(l.oid, c.relowner, 'MEMBER')
           ORDER BY c.oid::regclass::text LOOP
    severity := 'error';
    problem := format('this connection logs in as %s, which owns %s or is a member of its owner, and switched to %s: RESET ROLE leaves row-level security. Log in as the app role', r.login, r.tbl, v_me::regrole);
    RETURN NEXT;
  END LOOP;
  IF v_app IS NULL OR NOT pg_has_role(v_me, v_app, 'USAGE') THEN
    severity := 'error';
    problem := format('%s is not the policy''s app role %s, nor a member of it: the rules apply to %s only',
                      v_me::regrole, 'starter_app', 'starter_app');
    RETURN NEXT;
  END IF;
END $f$;

-- The partitions of each table with rules and the tables that inherit from one: row-level security on, with
-- no policies of their own, so they are read and written through it only (read directly, they would skip its rules
-- and triggers). Every apply and every migration: one made or attached since is closed too (it alone is locked,
-- as CHILD_TRIGGERS locks only one that lacks the triggers)
DO $rls$
DECLARE c regclass;
BEGIN
  FOR c IN WITH RECURSIVE d(oid) AS (
             SELECT i.inhrelid FROM pg_catalog.pg_inherits i
             WHERE i.inhparent = ANY (SELECT to_regclass(x)::oid FROM unnest(ARRAY['"app"."documents"']::text[]) x)
             UNION SELECT i.inhrelid FROM pg_catalog.pg_inherits i JOIN d ON i.inhparent = d.oid)
           SELECT d.oid::regclass FROM d JOIN pg_catalog.pg_class k ON k.oid = d.oid WHERE NOT k.relrowsecurity LOOP
    EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', c);
  END LOOP;
END $rls$;

-- The partitions of a table rowstile watches and the tables that inherit from it: the triggers made above, on
-- each, for the rows stored there and the statements on it
DO $ch$
DECLARE r record;
BEGIN
  FOR r IN SELECT * FROM authz_int.child_triggers() LOOP
    EXECUTE r.stmt;
    EXECUTE pg_catalog.format('COMMENT ON TRIGGER %I ON %s IS %L', r.name, r.child, 'rowstile: the trigger of the table above, for the rows stored here');
  END LOOP;
END $ch$;

REVOKE SELECT ON ALL TABLES IN SCHEMA authz_gen, authz_int FROM "starter_app";
GRANT SELECT ON authz_gen.policy_lines, authz_int."document__editor", authz_int."document__viewer" TO "starter_app";

-- Privileges the policy doesn't give on rowstile's schemas and what is in them are taken back
DO $r$
DECLARE g record; v_taken int := 0;
BEGIN
  FOR g IN SELECT n.nspname::text AS object, gw.who, a.privilege_type AS privilege,
       format('REVOKE %s ON SCHEMA %I FROM %s CASCADE', a.privilege_type, n.nspname, gw.who) AS stmt
  FROM pg_namespace n, aclexplode(n.nspacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int') AND a.grantee <> n.nspowner
    AND NOT (a.grantee = '"starter_app"'::regrole AND n.nspname <> 'authz_int' AND a.privilege_type = 'USAGE')
UNION ALL
SELECT c.oid::regclass::text, gw.who, a.privilege_type,
       format('REVOKE %s ON %s %s FROM %s CASCADE', a.privilege_type, CASE c.relkind WHEN 'S' THEN 'SEQUENCE' ELSE 'TABLE' END,
              c.oid::regclass, gw.who)
  FROM pg_class c, aclexplode(c.relacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> c.relowner
    AND NOT (a.grantee = '"starter_app"'::regrole AND a.privilege_type = 'SELECT'
             AND c.relnamespace::regnamespace::text || '."' || replace(c.relname, '"', '""') || '"' = ANY (ARRAY['authz_gen."policy_lines"', 'authz_int."document__editor"', 'authz_int."document__viewer"']::text[]))
UNION ALL
SELECT format('%s (%I)', c.oid::regclass, att.attname), gw.who, a.privilege_type,
       format('REVOKE %s (%I) ON %s FROM %s CASCADE', a.privilege_type, att.attname, c.oid::regclass, gw.who)
  FROM pg_class c JOIN pg_attribute att ON att.attrelid = c.oid, aclexplode(att.attacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND att.attacl IS NOT NULL
UNION ALL
SELECT p.oid::regprocedure::text, gw.who, a.privilege_type,
       format('REVOKE %s ON ROUTINE %s FROM %s CASCADE', a.privilege_type, p.oid::regprocedure, gw.who)
  FROM pg_proc p, aclexplode(p.proacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE p.pronamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> p.proowner
    AND NOT (p.pronamespace = 'authz_int'::regnamespace AND a.grantee IN (0, '"starter_app"'::regrole))
    AND NOT (p.pronamespace = 'authz_gen'::regnamespace AND a.grantee = '"starter_app"'::regrole
             AND '"' || replace(p.proname, '"', '""') || '"' = ANY (ARRAY['"app.documents:column owner_id:items"', '"app.documents:column owner_id:why"', '"app.documents:delete:items"', '"app.documents:delete:why"', '"app.documents:insert:items"', '"app.documents:insert:refuse"', '"app.documents:insert:why"', '"app.documents:rules:explain"', '"app.documents:update:items"', '"app.documents:update:refuse"', '"app.documents:update:why"']::text[]))
    AND NOT (p.pronamespace = 'authz'::regnamespace AND a.grantee = '"starter_app"'::regrole AND p.oid = ANY (ARRAY['authz.uid()', 'authz.principal()', 'authz.ctx(text)', 'authz.link_hashes()', 'authz.act_as(text, text)', 'authz.sign_out()', 'authz.connection_check()', 'authz.session_limited()', 'authz.can(text, text, text)', 'authz.list(text, text, text, integer)', 'authz.perms(text, text)', 'authz.perms_of(text, text[])', 'authz.share(text, text, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, text, text, text, text, text)', 'authz.create_link(text, text, text, timestamptz)', 'authz.list_links(text, text)', 'authz.revoke_link(text, text, text)', 'authz.create_role(text, text, text, text, text[])', 'authz.set_role_permissions(bigint, text[])', 'authz.delete_role(bigint)', 'authz.roles_of(text, text)', 'authz.who(text, text, text)', 'authz.explain(text, text, text, text)', 'authz.list_shares(text, text)', 'authz.explain_rule(text, text, text, jsonb)', 'authz.who_among(text, text, text, text[], text)', 'authz.create_api_key(text, text, timestamptz, text, text)', 'authz.list_api_keys(text, text)', 'authz.revoke_api_key(bigint)', 'authz.login_key(text)', 'authz.login_jwt(text)', 'authz.view_as(text, text)', 'authz.request_access(text, text, text, text, interval)', 'authz.pending_requests()', 'authz.decide_request(bigint, boolean, text)', 'authz.cancel_request(bigint)', 'authz.break_glass(text, text, text, text, interval)', 'authz.start_review(text, text, timestamptz)', 'authz.review_items(bigint)', 'authz.review_decide(bigint, integer, boolean)', 'authz.close_review(bigint, boolean)', 'authz.who(text, bigint, text)', 'authz.explain(text, bigint, text, text)', 'authz.list_shares(text, bigint)', 'authz.list_links(text, bigint)', 'authz.revoke_link(text, bigint, text)', 'authz.create_link(text, bigint, text, timestamptz)', 'authz.create_role(text, bigint, text, text, text[])', 'authz.roles_of(text, bigint)', 'authz.request_access(text, bigint, text, text, interval)', 'authz.break_glass(text, bigint, text, text, interval)', 'authz.start_review(text, bigint, timestamptz)', 'authz.can(text, bigint, text)', 'authz.who_among(text, bigint, text, text[], text)', 'authz.perms(text, bigint)', 'authz.share(text, text, text, text, bigint, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, text, text, text, bigint, text)', 'authz.share(text, bigint, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, bigint, text, text, text, text)', 'authz.share(text, bigint, text, text, bigint, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, bigint, text, text, bigint, text)']::regprocedure[])) LOOP
    EXECUTE g.stmt;
    v_taken := v_taken + 1;
  END LOOP;
  IF v_taken > 0 THEN
    RAISE WARNING 'took back % privileges on rowstile''s schemas that the policy doesn''t give (default privileges of the owner, or grants made since the last apply)', v_taken;
  END IF;
END $r$;

REVOKE ALL ON ALL FUNCTIONS IN SCHEMA authz FROM PUBLIC;

GRANT USAGE ON SCHEMA authz, authz_gen TO "starter_app";

REVOKE ALL ON ALL FUNCTIONS IN SCHEMA authz_gen FROM PUBLIC;

DO $gf$
DECLARE f regprocedure;
BEGIN
  FOR f IN SELECT p.oid::regprocedure FROM pg_proc p WHERE p.pronamespace = 'authz_gen'::regnamespace
           AND '"' || replace(p.proname, '"', '""') || '"' = ANY (ARRAY['"app.documents:column owner_id:items"', '"app.documents:column owner_id:why"', '"app.documents:delete:items"', '"app.documents:delete:why"', '"app.documents:insert:items"', '"app.documents:insert:refuse"', '"app.documents:insert:why"', '"app.documents:rules:explain"', '"app.documents:update:items"', '"app.documents:update:refuse"', '"app.documents:update:why"']::text[]) LOOP
    EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO %I', f, 'starter_app');
  END LOOP;
END $gf$;

